--
-- TOC entry 323 (class 1255 OID 39440)
-- Name: l043_dms_case_add(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: PROCEDURE; Schema: docsvc; Owner: app_user
--

CREATE PROCEDURE docsvc.l043_dms_case_add(IN pv_object_type character varying, IN pv_object_ref character varying, IN pv_branch_code character varying, IN pv_customer_number character varying, IN pv_customer_name character varying, IN pv_product_type_code character varying, IN pv_request_type_code character varying, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_workflow_version integer;
    v_initial_state varchar;
    v_case_id uuid;
BEGIN
    IF btrim(COALESCE(pv_object_type, '')) = ''
       OR btrim(COALESCE(pv_object_ref, '')) = ''
       OR btrim(COALESCE(pv_branch_code, '')) = ''
       OR btrim(COALESCE(pv_customer_number, '')) = ''
       OR btrim(COALESCE(pv_customer_name, '')) = ''
       OR btrim(COALESCE(pv_product_type_code, '')) = ''
       OR btrim(COALESCE(pv_request_type_code, '')) = '' THEN
        RAISE EXCEPTION 'Case type, product type, request type, contract reference, branch and customer information are required';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM docsvc.product_type product
        JOIN docsvc.request_type request
          ON request.product_type_code = product.product_type_code
        WHERE product.product_type_code = btrim(pv_product_type_code)
          AND product.active = TRUE
          AND request.request_type_code = btrim(pv_request_type_code)
          AND request.active = TRUE
    ) THEN
        RAISE EXCEPTION 'Request type "%" does not belong to active product type "%"',
            btrim(pv_request_type_code), btrim(pv_product_type_code);
    END IF;

    IF EXISTS (
        SELECT 1 FROM docsvc.portal_case
        WHERE object_type = btrim(pv_object_type)
          AND object_ref = btrim(pv_object_ref)
          AND state <> 'CANCELLED'
    ) THEN
        RAISE EXCEPTION 'An active case already exists for % / %', btrim(pv_object_type), btrim(pv_object_ref);
    END IF;

    SELECT version, COALESCE(definition ->> 'initial', 'DRAFT')
      INTO v_workflow_version, v_initial_state
      FROM docsvc.portal_workflow_definition
     WHERE object_type = btrim(pv_object_type)
     ORDER BY version DESC LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No workflow definition is configured for case type %', btrim(pv_object_type);
    END IF;

    v_case_id := gen_random_uuid();
    INSERT INTO docsvc.portal_case (
        case_id, object_type, object_ref, branch_code, state, maker, submitted_by, checker, authorised_by,
        created_at, updated_at, workflow_version, customer_number, customer_name,
        product_type_code, request_type_code, amendment_no, amendment_reason, opened_by
    ) VALUES (
        v_case_id, btrim(pv_object_type), btrim(pv_object_ref), btrim(pv_branch_code), v_initial_state,
        NULLIF(btrim(sessioninfo_username), ''), NULL, NULL, NULL, now(), now(), v_workflow_version,
        btrim(pv_customer_number), btrim(pv_customer_name), btrim(pv_product_type_code), btrim(pv_request_type_code),
        0, NULL, NULLIF(btrim(sessioninfo_username), '')
    );

    INSERT INTO docsvc.portal_case_event (case_id, event_time, actor, action, remarks)
    VALUES (v_case_id, now(), NULLIF(btrim(sessioninfo_username), ''), 'CREATE', 'Created from Legacy Search 03L43');
END;
$$;


ALTER PROCEDURE docsvc.l043_dms_case_add(IN pv_object_type character varying, IN pv_object_ref character varying, IN pv_branch_code character varying, IN pv_customer_number character varying, IN pv_customer_name character varying, IN pv_product_type_code character varying, IN pv_request_type_code character varying, IN sessioninfo_username character varying) OWNER TO app_user;

