--
-- TOC entry 311 (class 1255 OID 39314)
-- Name: l049_document_type_add(character varying, character varying, text, character varying, boolean, jsonb, integer, character varying); Type: PROCEDURE; Schema: docsvc; Owner: app_user
--

CREATE PROCEDURE docsvc.l049_document_type_add(IN pv_type_code character varying, IN pv_category_code character varying, IN pv_description text, IN pv_retention_class character varying, IN pv_active boolean, IN pv_allowed_extensions jsonb, IN pv_max_file_size_mb integer, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_extensions jsonb;
BEGIN
    IF NULLIF(btrim(pv_type_code), '') IS NULL OR NULLIF(btrim(pv_category_code), '') IS NULL OR NULLIF(btrim(pv_description), '') IS NULL THEN
        RAISE EXCEPTION 'Type code, category code, and description are required';
    END IF;
    IF pv_max_file_size_mb IS NULL OR pv_max_file_size_mb NOT BETWEEN 1 AND 10240 THEN
        RAISE EXCEPTION 'Maximum file size must be between 1 and 10240 MB';
    END IF;
    IF jsonb_typeof(COALESCE(pv_allowed_extensions, '[]'::jsonb)) <> 'array' OR jsonb_array_length(COALESCE(pv_allowed_extensions, '[]'::jsonb)) = 0 THEN
        RAISE EXCEPTION 'At least one allowed file extension is required';
    END IF;
    SELECT jsonb_agg(extension ORDER BY extension) INTO v_extensions
      FROM (SELECT DISTINCT lower(btrim(value)) AS extension FROM jsonb_array_elements_text(pv_allowed_extensions)) extension_values
     WHERE extension ~ '^[a-z0-9]+$';
    IF v_extensions IS NULL OR jsonb_array_length(v_extensions) <> jsonb_array_length(pv_allowed_extensions) THEN
        RAISE EXCEPTION 'Allowed file extensions must be non-empty alphanumeric extension names without dots';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM docsvc.doc_category WHERE category_code = btrim(pv_category_code)) THEN
        RAISE EXCEPTION 'Document category "%" was not found', btrim(pv_category_code);
    END IF;
    IF NULLIF(btrim(pv_retention_class), '') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM docsvc.retention_policy WHERE retention_class = btrim(pv_retention_class)) THEN
        RAISE EXCEPTION 'Retention class "%" was not found', btrim(pv_retention_class);
    END IF;
    INSERT INTO docsvc.doc_type (type_code, category_code, description, retention_class, active, allowed_extensions, max_file_size_mb)
    VALUES (btrim(pv_type_code), btrim(pv_category_code), btrim(pv_description), NULLIF(btrim(pv_retention_class), ''), COALESCE(pv_active, TRUE), v_extensions, pv_max_file_size_mb);
EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Document type "%" already exists', btrim(pv_type_code);
END;
$_$;


ALTER PROCEDURE docsvc.l049_document_type_add(IN pv_type_code character varying, IN pv_category_code character varying, IN pv_description text, IN pv_retention_class character varying, IN pv_active boolean, IN pv_allowed_extensions jsonb, IN pv_max_file_size_mb integer, IN sessioninfo_username character varying) OWNER TO app_user;

