CREATE PROCEDURE docsvc.l079_product_type_update(IN pv_product_type_code character varying, IN pv_description text, IN pv_active boolean, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NULLIF(btrim(pv_product_type_code), '') IS NULL OR NULLIF(btrim(pv_description), '') IS NULL THEN
        RAISE EXCEPTION 'Product type code and description are required';
    END IF;
    UPDATE docsvc.product_type
       SET description = btrim(pv_description), active = COALESCE(pv_active, FALSE)
     WHERE product_type_code = btrim(pv_product_type_code);
    IF NOT FOUND THEN RAISE EXCEPTION 'Product type "%" was not found', btrim(pv_product_type_code); END IF;
END;
$$;


ALTER PROCEDURE docsvc.l079_product_type_update(IN pv_product_type_code character varying, IN pv_description text, IN pv_active boolean, IN sessioninfo_username character varying) OWNER TO app_user;

--
-- TOC entry 315 (class 1255 OID 39353)
-- Name: l081_request_type_add(character varying, character varying, text, boolean, character varying); Type: PROCEDURE; Schema: docsvc; Owner: app_user
--

CREATE PROCEDURE docsvc.l081_request_type_add(IN pv_request_type_code character varying, IN pv_product_type_code character varying, IN pv_description text, IN pv_active boolean, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NULLIF(btrim(pv_request_type_code), '') IS NULL OR NULLIF(btrim(pv_product_type_code), '') IS NULL OR NULLIF(btrim(pv_description), '') IS NULL THEN
        RAISE EXCEPTION 'Request type code, product type code, and description are required';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM docsvc.product_type WHERE product_type_code = btrim(pv_product_type_code)) THEN
        RAISE EXCEPTION 'Product type "%" was not found', btrim(pv_product_type_code);
    END IF;
    INSERT INTO docsvc.request_type (request_type_code, product_type_code, description, active)
    VALUES (btrim(pv_request_type_code), btrim(pv_product_type_code), btrim(pv_description), COALESCE(pv_active, TRUE));
EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Request type "%" already exists', btrim(pv_request_type_code);
END;
$$;


ALTER PROCEDURE docsvc.l081_request_type_add(IN pv_request_type_code character varying, IN pv_product_type_code character varying, IN pv_description text, IN pv_active boolean, IN sessioninfo_username character varying) OWNER TO app_user;

