--
-- TOC entry 320 (class 1255 OID 39413)
-- Name: l083_document_requirement_rule_add(bigint, character varying, character varying, character varying, character varying, boolean, date, date, boolean, character varying); Type: PROCEDURE; Schema: docsvc; Owner: app_user
--

CREATE PROCEDURE docsvc.l083_document_requirement_rule_add(IN pv_rule_id bigint, IN pv_product_type_code character varying, IN pv_request_type_code character varying, IN pv_category_code character varying, IN pv_type_code character varying, IN pv_is_required boolean, IN pv_effective_from date, IN pv_effective_to date, IN pv_active boolean, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NULLIF(btrim(pv_product_type_code),'') IS NULL OR NULLIF(btrim(pv_request_type_code),'') IS NULL OR NULLIF(btrim(pv_category_code),'') IS NULL OR NULLIF(btrim(pv_type_code),'') IS NULL THEN
        RAISE EXCEPTION 'Product type, request type, document category, and document type are required';
    END IF;
    IF pv_effective_to IS NOT NULL AND pv_effective_to < COALESCE(pv_effective_from, CURRENT_DATE) THEN RAISE EXCEPTION 'Effective to date must not precede effective from date'; END IF;
    IF NOT EXISTS (SELECT 1 FROM docsvc.request_type WHERE request_type_code=btrim(pv_request_type_code) AND product_type_code=btrim(pv_product_type_code)) THEN RAISE EXCEPTION 'Request type "%" does not belong to product type "%"', btrim(pv_request_type_code), btrim(pv_product_type_code); END IF;
    IF NOT EXISTS (SELECT 1 FROM docsvc.doc_type WHERE type_code=btrim(pv_type_code) AND category_code=btrim(pv_category_code)) THEN RAISE EXCEPTION 'Document type "%" does not belong to category "%"', btrim(pv_type_code), btrim(pv_category_code); END IF;
    INSERT INTO docsvc.document_requirement_rule (product_type_code,request_type_code,category_code,type_code,is_required,effective_from,effective_to,active)
    VALUES (btrim(pv_product_type_code),btrim(pv_request_type_code),btrim(pv_category_code),btrim(pv_type_code),COALESCE(pv_is_required,TRUE),COALESCE(pv_effective_from,CURRENT_DATE),pv_effective_to,COALESCE(pv_active,TRUE));
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'A requirement rule with the same request, document type, and effective date already exists';
END;
$$;


ALTER PROCEDURE docsvc.l083_document_requirement_rule_add(IN pv_rule_id bigint, IN pv_product_type_code character varying, IN pv_request_type_code character varying, IN pv_category_code character varying, IN pv_type_code character varying, IN pv_is_required boolean, IN pv_effective_from date, IN pv_effective_to date, IN pv_active boolean, IN sessioninfo_username character varying) OWNER TO app_user;

