--
-- TOC entry 321 (class 1255 OID 39414)
-- Name: l083_document_requirement_rule_update(bigint, character varying, character varying, character varying, character varying, boolean, date, date, boolean, character varying); Type: PROCEDURE; Schema: docsvc; Owner: app_user
--

CREATE PROCEDURE docsvc.l083_document_requirement_rule_update(IN pv_rule_id bigint, IN pv_product_type_code character varying, IN pv_request_type_code character varying, IN pv_category_code character varying, IN pv_type_code character varying, IN pv_is_required boolean, IN pv_effective_from date, IN pv_effective_to date, IN pv_active boolean, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF pv_rule_id IS NULL THEN RAISE EXCEPTION 'Rule ID is required'; END IF;
    IF NULLIF(btrim(pv_product_type_code),'') IS NULL OR NULLIF(btrim(pv_request_type_code),'') IS NULL OR NULLIF(btrim(pv_category_code),'') IS NULL OR NULLIF(btrim(pv_type_code),'') IS NULL THEN RAISE EXCEPTION 'Product type, request type, document category, and document type are required'; END IF;
    IF pv_effective_to IS NOT NULL AND pv_effective_to < COALESCE(pv_effective_from, CURRENT_DATE) THEN RAISE EXCEPTION 'Effective to date must not precede effective from date'; END IF;
    IF NOT EXISTS (SELECT 1 FROM docsvc.request_type WHERE request_type_code=btrim(pv_request_type_code) AND product_type_code=btrim(pv_product_type_code)) THEN RAISE EXCEPTION 'Request type "%" does not belong to product type "%"', btrim(pv_request_type_code), btrim(pv_product_type_code); END IF;
    IF NOT EXISTS (SELECT 1 FROM docsvc.doc_type WHERE type_code=btrim(pv_type_code) AND category_code=btrim(pv_category_code)) THEN RAISE EXCEPTION 'Document type "%" does not belong to category "%"', btrim(pv_type_code), btrim(pv_category_code); END IF;
    UPDATE docsvc.document_requirement_rule SET product_type_code=btrim(pv_product_type_code),request_type_code=btrim(pv_request_type_code),category_code=btrim(pv_category_code),type_code=btrim(pv_type_code),is_required=COALESCE(pv_is_required,FALSE),effective_from=COALESCE(pv_effective_from,CURRENT_DATE),effective_to=pv_effective_to,active=COALESCE(pv_active,FALSE) WHERE rule_id=pv_rule_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Document requirement rule "%" was not found', pv_rule_id; END IF;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'A requirement rule with the same request, document type, and effective date already exists';
END;
$$;


ALTER PROCEDURE docsvc.l083_document_requirement_rule_update(IN pv_rule_id bigint, IN pv_product_type_code character varying, IN pv_request_type_code character varying, IN pv_category_code character varying, IN pv_type_code character varying, IN pv_is_required boolean, IN pv_effective_from date, IN pv_effective_to date, IN pv_active boolean, IN sessioninfo_username character varying) OWNER TO app_user;

--
-- TOC entry 297 (class 1255 OID 16485)
-- Name: sp_doc_category_bycaselst(text, refcursor); Type: PROCEDURE; Schema: docsvc; Owner: app_user
--

CREATE PROCEDURE docsvc.sp_doc_category_bycaselst(IN p_case_id text, INOUT p_cursor refcursor DEFAULT 'p_cursor'::refcursor)
    LANGUAGE plpgsql
    AS $$
BEGIN
    OPEN p_cursor FOR
        SELECT
            '' AS images,
            category.category_code AS value,
            category.description AS text
        FROM docsvc.portal_case AS portal_case
        JOIN docsvc.doc_category AS category
          ON category.object_type = portal_case.object_type
        WHERE portal_case.case_id::text = btrim(p_case_id)
          AND category.active = TRUE
        ORDER BY category.category_code;
END;
$$;


ALTER PROCEDURE docsvc.sp_doc_category_bycaselst(IN p_case_id text, INOUT p_cursor refcursor) OWNER TO app_user;

