--
-- TOC entry 310 (class 1255 OID 39316)
-- Name: sp_fileconfig_bycaselst(character varying, character varying, refcursor); Type: PROCEDURE; Schema: docsvc; Owner: app_user
--

CREATE PROCEDURE docsvc.sp_fileconfig_bycaselst(IN pv_category_code character varying, IN pv_type_code character varying, INOUT p_cursor refcursor DEFAULT 'p_cursor'::refcursor)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NULLIF(btrim(pv_category_code), '') IS NOT NULL
       AND NULLIF(btrim(pv_type_code), '') IS NOT NULL THEN
        OPEN p_cursor FOR
            SELECT a.allowed_extensions::text AS allowed_extensions,
                   a.max_file_size_mb
              FROM docsvc.doc_type a
             WHERE a.category_code = btrim(pv_category_code)
               AND a.type_code = btrim(pv_type_code)
               AND a.active = TRUE;
    ELSE
        OPEN p_cursor FOR
            SELECT NULL::text AS allowed_extensions,
                   NULL::integer AS max_file_size_mb
             WHERE FALSE;
    END IF;
END;
$$;


ALTER PROCEDURE docsvc.sp_fileconfig_bycaselst(IN pv_category_code character varying, IN pv_type_code character varying, INOUT p_cursor refcursor) OWNER TO app_user;

