-- Name: create_notification(character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, jsonb, timestamp with time zone, character varying, character varying, character varying); Type: FUNCTION; Schema: app; Owner: app_user
--

CREATE FUNCTION app.create_notification(p_user_email character varying, p_title character varying, p_message text DEFAULT NULL::text, p_type character varying DEFAULT 'info'::character varying, p_category character varying DEFAULT 'system'::character varying, p_severity character varying DEFAULT 'normal'::character varying, p_source character varying DEFAULT NULL::character varying, p_entity_type character varying DEFAULT NULL::character varying, p_entity_id character varying DEFAULT NULL::character varying, p_action_url character varying DEFAULT NULL::character varying, p_metadata jsonb DEFAULT '{}'::jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_created_by character varying DEFAULT NULL::character varying, p_recipient_scope character varying DEFAULT 'USER'::character varying, p_recipient_key character varying DEFAULT NULL::character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id BIGINT;
    v_user_email VARCHAR(200);
    v_recipient_scope VARCHAR(20);
    v_recipient_key VARCHAR(200);
BEGIN
    v_user_email := lower(trim(coalesce(p_user_email, '')));
    v_recipient_scope := upper(trim(coalesce(p_recipient_scope, 'USER')));
    v_recipient_key := coalesce(nullif(trim(coalesce(p_recipient_key, '')), ''), v_user_email);

    IF v_user_email = '' THEN
        RAISE EXCEPTION 'user_email is required';
    END IF;

    INSERT INTO "app"."notification_inbox" (
        "user_email",
        "recipient_scope",
        "recipient_key",
        "title",
        "message",
        "type",
        "category",
        "severity",
        "source",
        "entity_type",
        "entity_id",
        "action_url",
        "metadata",
        "created_at",
        "expires_at",
        "created_by"
    )
    VALUES (
        v_user_email,
        v_recipient_scope,
        v_recipient_key,
        p_title,
        p_message,
        lower(trim(coalesce(p_type, 'info'))),
        lower(trim(coalesce(p_category, 'system'))),
        lower(trim(coalesce(p_severity, 'normal'))),
        nullif(trim(coalesce(p_source, '')), ''),
        nullif(trim(coalesce(p_entity_type, '')), ''),
        nullif(trim(coalesce(p_entity_id, '')), ''),
        nullif(trim(coalesce(p_action_url, '')), ''),
        coalesce(p_metadata, '{}'::jsonb),
        NOW(),
        p_expires_at,
        nullif(trim(coalesce(p_created_by, '')), '')
    )
    RETURNING "id" INTO v_id;

    INSERT INTO "app"."notification_history" (
        "id", "user_email", "recipient_scope", "recipient_key",
        "title", "message", "type", "category", "severity",
        "source", "entity_type", "entity_id", "action_url", "metadata",
        "created_at", "expires_at", "created_by", "read_at", "dismissed_at"
    )
    SELECT
        "id", "user_email", "recipient_scope", "recipient_key",
        "title", "message", "type", "category", "severity",
        "source", "entity_type", "entity_id", "action_url", "metadata",
        "created_at", "expires_at", "created_by", "read_at", "dismissed_at"
    FROM "app"."notification_inbox"
    WHERE "id" = v_id;

    INSERT INTO "app"."notification_audit" (
        "id", "user_email", "recipient_scope", "recipient_key",
        "title", "message", "type", "category", "severity",
        "source", "entity_type", "entity_id", "action_url", "metadata",
        "created_at", "expires_at", "created_by", "read_at", "dismissed_at"
    )
    SELECT
        "id", "user_email", "recipient_scope", "recipient_key",
        "title", "message", "type", "category", "severity",
        "source", "entity_type", "entity_id", "action_url", "metadata",
        "created_at", "expires_at", "created_by", "read_at", "dismissed_at"
