--

CREATE PROCEDURE app.l012_announcement_del(IN pv_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_row_count" INTEGER;
BEGIN
    DELETE FROM "app"."announcement"
    WHERE "id" = "pv_id";

    GET DIAGNOSTICS "v_row_count" = ROW_COUNT;

    IF "v_row_count" = 0 THEN
        RAISE EXCEPTION 'Announcement with id "%" not found', "pv_id";
    END IF;

EXCEPTION
    WHEN foreign_key_violation THEN
        RAISE EXCEPTION 'Cannot delete announcement "%" because it is referenced by other records', "pv_id";
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to delete announcement: %', SQLERRM;
END;
$$;


