--

CREATE PROCEDURE app.l012_announcement_ins(IN pv_title character varying, IN pv_content text DEFAULT NULL::text, IN pv_type character varying DEFAULT 'info'::character varying, IN pv_status character varying DEFAULT 'draft'::character varying, IN pv_priority integer DEFAULT 0, IN pv_audience_scope character varying DEFAULT 'ALL'::character varying, IN pv_audience_key character varying DEFAULT NULL::character varying, IN pv_version character varying DEFAULT NULL::character varying, IN pv_deploy_at timestamp with time zone DEFAULT NULL::timestamp with time zone, IN pv_link_url character varying DEFAULT NULL::character varying, IN pv_metadata jsonb DEFAULT NULL::jsonb, IN pv_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, IN pv_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, IN _v_username character varying DEFAULT NULL::character varying, IN _v_email character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_title" VARCHAR(200);
    "v_type" VARCHAR(20);
    "v_status" VARCHAR(20);
    "v_audience_scope" VARCHAR(20);
    "v_actor" VARCHAR(200);
    "v_start_date" TIMESTAMPTZ;
BEGIN
    "v_title" := nullif(trim(coalesce("pv_title", '')), '');
    "v_type" := lower(trim(coalesce("pv_type", 'info')));
    "v_status" := lower(trim(coalesce("pv_status", 'draft')));
    "v_audience_scope" := upper(trim(coalesce("pv_audience_scope", 'ALL')));
    "v_actor" := nullif(trim(coalesce("_v_username", "_v_email", 'system')), '');
    "v_start_date" := coalesce("pv_start_date", NOW());

    IF "v_title" IS NULL THEN
        RAISE EXCEPTION 'Announcement title is required';
    END IF;

    IF "v_type" NOT IN ('info', 'update', 'deploy', 'maintenance') THEN
        RAISE EXCEPTION 'Unsupported announcement type: %', "pv_type";
    END IF;

    IF "v_status" NOT IN ('draft', 'published', 'archived') THEN
        RAISE EXCEPTION 'Unsupported announcement status: %', "pv_status";
    END IF;

    IF "v_audience_scope" NOT IN ('ALL', 'COMPONENT', 'ROLE') THEN
        RAISE EXCEPTION 'Unsupported announcement audience scope: %', "pv_audience_scope";
    END IF;

    IF "pv_end_date" IS NOT NULL AND "pv_end_date" < "v_start_date" THEN
        RAISE EXCEPTION 'Announcement end date must be greater than or equal to start date';
    END IF;

    INSERT INTO "app"."announcement" (
        "title",
        "content",
        "type",
        "status",
        "priority",
        "audience_scope",
        "audience_key",
        "version",
        "deploy_at",
        "link_url",
        "metadata",
        "start_date",
        "end_date",
        "created_by",
        "created_at",
        "modified_by",
        "modified_at"
    )
    VALUES (
        "v_title",
        nullif("pv_content", ''),
        "v_type",
        "v_status",
        coalesce("pv_priority", 0),
        "v_audience_scope",
        nullif(trim(coalesce("pv_audience_key", '')), ''),
        nullif(trim(coalesce("pv_version", '')), ''),
        "pv_deploy_at",
        nullif(trim(coalesce("pv_link_url", '')), ''),
        coalesce("pv_metadata", '{}'::jsonb),
        "v_start_date",
        "pv_end_date",
        "v_actor",
        NOW(),
        "v_actor",
        NOW()
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to insert announcement: %', SQLERRM;
END;
$$;


