--

CREATE PROCEDURE app.l012_announcement_upd(IN pv_id bigint, IN pv_title character varying DEFAULT NULL::character varying, IN pv_content text DEFAULT NULL::text, IN pv_type character varying DEFAULT NULL::character varying, IN pv_status character varying DEFAULT NULL::character varying, IN pv_priority integer DEFAULT NULL::integer, IN pv_audience_scope character varying DEFAULT NULL::character varying, IN pv_audience_key character varying DEFAULT NULL::character varying, IN pv_version character varying DEFAULT NULL::character varying, IN pv_deploy_at timestamp with time zone DEFAULT NULL::timestamp with time zone, IN pv_link_url character varying DEFAULT NULL::character varying, IN pv_metadata jsonb DEFAULT NULL::jsonb, IN pv_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, IN pv_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, IN _v_username character varying DEFAULT NULL::character varying, IN _v_email character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_row_count" INTEGER;
    "v_title" VARCHAR(200);
    "v_type" VARCHAR(20);
    "v_status" VARCHAR(20);
    "v_audience_scope" VARCHAR(20);
    "v_actor" VARCHAR(200);
    "v_start_date" TIMESTAMPTZ;
    "v_end_date" TIMESTAMPTZ;
BEGIN
    IF "pv_id" IS NULL THEN
        RAISE EXCEPTION 'Announcement id is required';
    END IF;

    SELECT
        coalesce(nullif(trim(coalesce("pv_title", '')), ''), "title"),
        lower(trim(coalesce("pv_type", "type"))),
        lower(trim(coalesce("pv_status", "status"))),
        upper(trim(coalesce("pv_audience_scope", "audience_scope"))),
        coalesce("pv_start_date", "start_date"),
        coalesce("pv_end_date", "end_date")
    INTO
        "v_title",
        "v_type",
        "v_status",
        "v_audience_scope",
        "v_start_date",
        "v_end_date"
    FROM "app"."announcement"
    WHERE "id" = "pv_id";

    IF "v_title" IS NULL THEN
        RAISE EXCEPTION 'Announcement with id "%" not found', "pv_id";
    END IF;

    IF "v_type" NOT IN ('info', 'update', 'deploy', 'maintenance') THEN
        RAISE EXCEPTION 'Unsupported announcement type: %', "pv_type";
    END IF;

    IF "v_status" NOT IN ('draft', 'published', 'archived') THEN
        RAISE EXCEPTION 'Unsupported announcement status: %', "pv_status";
    END IF;

    IF "v_audience_scope" NOT IN ('ALL', 'COMPONENT', 'ROLE') THEN
        RAISE EXCEPTION 'Unsupported announcement audience scope: %', "pv_audience_scope";
    END IF;

    IF "v_end_date" IS NOT NULL AND "v_end_date" < "v_start_date" THEN
        RAISE EXCEPTION 'Announcement end date must be greater than or equal to start date';
    END IF;

    "v_actor" := nullif(trim(coalesce("_v_username", "_v_email", 'system')), '');

    UPDATE "app"."announcement"
    SET
        "title" = "v_title",
        "content" = coalesce("pv_content", "content"),
        "type" = "v_type",
        "status" = "v_status",
        "priority" = coalesce("pv_priority", "priority"),
        "audience_scope" = "v_audience_scope",
        "audience_key" = coalesce(nullif(trim(coalesce("pv_audience_key", '')), ''), "audience_key"),
        "version" = coalesce(nullif(trim(coalesce("pv_version", '')), ''), "version"),
        "deploy_at" = coalesce("pv_deploy_at", "deploy_at"),
        "link_url" = coalesce(nullif(trim(coalesce("pv_link_url", '')), ''), "link_url"),
        "metadata" = coalesce("pv_metadata", "metadata"),
        "start_date" = "v_start_date",
        "end_date" = coalesce("v_end_date", "end_date"),
        "modified_by" = "v_actor",
        "modified_at" = NOW()
    WHERE "id" = "pv_id";

    GET DIAGNOSTICS "v_row_count" = ROW_COUNT;

    IF "v_row_count" = 0 THEN
        RAISE EXCEPTION 'Announcement with id "%" not found', "pv_id";
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to update announcement: %', SQLERRM;
END;
$$;


