--
-- TOC entry 222 (class 1255 OID 20174)
-- Name: sp_groups_add(character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: PROCEDURE; Schema: public; Owner: app_user
--

CREATE PROCEDURE public.sp_groups_add(IN pv_group_code character varying, IN pv_orgid character varying, IN pv_groupname character varying, IN pv_group_acronym character varying, IN pv_status character varying, IN pv_description character varying, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count  INTEGER;
    v_count1 INTEGER;
    v_count2 INTEGER;
BEGIN
    -- Validate length
    IF LENGTH(pv_groupname) > 50 THEN
        RAISE EXCEPTION 'Ten nhom NSD toi da 50 ky tu';
    END IF;

    IF LENGTH(pv_group_acronym) > 50 THEN
        RAISE EXCEPTION 'Ten viet tat toi da 50 ky tu';
    END IF;

    IF LENGTH(pv_description) > 200 THEN
        RAISE EXCEPTION 'Dien giai toi da 200 ky tu';
    END IF;

    -- Check duplicate GROUPNAME
    SELECT COUNT(*)
    INTO v_count
    FROM groups
    WHERE UPPER(groupname) = UPPER(pv_groupname)
      AND is_deleted = 'N';

    -- Check duplicate GROUP_CODE
    SELECT COUNT(*)
    INTO v_count1
    FROM groups
    WHERE UPPER(group_code) = UPPER(pv_group_code)
      AND is_deleted = 'N';

    -- Check duplicate GROUP_ACRONYM
    SELECT COUNT(*)
    INTO v_count2
    FROM groups
    WHERE UPPER(group_acronym) = UPPER(pv_group_acronym)
      AND is_deleted = 'N';

    IF v_count > 0 THEN
        RAISE EXCEPTION 'Ten nhom da ton tai';
    END IF;

    IF v_count1 > 0 THEN
        RAISE EXCEPTION 'Ma nhom da ton tai';
    END IF;

    IF v_count2 > 0 THEN
        RAISE EXCEPTION 'Ten viet tat da ton tai';
    END IF;

    INSERT INTO groups (
        group_id,
        groupname,
        status,
        createdate,
        lastmodify,
        usertype,
        is_deleted,
        grptype,
        description,
        created_by,
        modified_by,
        group_code,
        orgid,
        group_acronym
    )
    VALUES (
        nextval('seq_groups'),
        UPPER(pv_groupname),
        pv_status,
        CURRENT_TIMESTAMP,
        NULL,
        NULL,
        'N',
        NULL,
        pv_description,
        sessioninfo_username,
        NULL,
        UPPER(pv_group_code),
        pv_orgid::integer,
        pv_group_acronym
    );
END;
$$;


ALTER PROCEDURE public.sp_groups_add(IN pv_group_code character varying, IN pv_orgid character varying, IN pv_groupname character varying, IN pv_group_acronym character varying, IN pv_status character varying, IN pv_description character varying, IN sessioninfo_username character varying) OWNER TO app_user;

--
-- TOC entry 223 (class 1255 OID 20175)
-- Name: sp_groups_del(numeric, character varying); Type: PROCEDURE; Schema: public; Owner: app_user
--

CREATE PROCEDURE public.sp_groups_del(IN pv_group_id numeric, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count1 VARCHAR(10);
    v_count2 INTEGER;
BEGIN
   
    -- Soft delete
    UPDATE groups
    SET
        is_deleted = 'Y',
        lastmodify = CURRENT_TIMESTAMP,
        modified_by = sessioninfo_username
    WHERE group_id = pv_group_id
      AND is_deleted = 'N';
END;
$$;


ALTER PROCEDURE public.sp_groups_del(IN pv_group_id numeric, IN sessioninfo_username character varying) OWNER TO app_user;

--
-- TOC entry 224 (class 1255 OID 20176)
-- Name: sp_groups_upd(character varying, character varying, character varying, character varying, numeric, character varying); Type: PROCEDURE; Schema: public; Owner: app_user
--

CREATE PROCEDURE public.sp_groups_upd(IN pv_groupname character varying, IN pv_group_acronym character varying, IN pv_status character varying, IN pv_description character varying, IN pv_group_id numeric, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE groups
    SET groupname     = UPPER(pv_groupname),
        status        = pv_status,
        description   = pv_description,
        lastmodify    = CURRENT_TIMESTAMP,
        group_acronym = UPPER(pv_group_acronym),
        modified_by   = sessioninfo_username
    WHERE group_id = pv_group_id;
END;
$$;


