--
-- TOC entry 393 (class 1255 OID 20231)
-- Name: get_user(text, text, text); Type: FUNCTION; Schema: auth; Owner: app_user
--

CREATE FUNCTION auth.get_user(p_email text, p_password text, p_type text) RETURNS TABLE(id integer, display_name character varying, password character varying, is_privileged_account boolean, type character varying, status character, is_deleted character, created_date timestamp without time zone, created_user character varying, modified_date timestamp without time zone, modified_by character varying, email character varying, last_login timestamp without time zone, allow_public boolean, avatar_url character varying, setting jsonb, auth_ok boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        u.id,
        u.display_name,
        u.password,
        u.is_privileged_account,
        u.type,
        u.status,
        u.is_deleted,
        u.created_date,
        u.created_user,
        u.modified_date,
        u.modified_by,
        u.email,
        u.last_login,
        u.allow_public,
        u.avatar_url,
        u.setting,
        true::boolean AS auth_ok
    FROM auth."user" AS u
    WHERE u.email = p_email
      AND (
          (lower(coalesce(p_type, '')) = 'local'
              AND u.password IS NOT NULL
              AND auth.crypt(p_password, u.password) = u.password)
          OR (lower(coalesce(p_type, '')) <> 'local'
              AND (p_type IS NULL OR u.type = p_type))
      );
END;
$$;


ALTER FUNCTION auth.get_user(p_email text, p_password text, p_type text) OWNER TO app_user;

--
-- TOC entry 375 (class 1255 OID 20232)
-- Name: get_user_and_tags(text, text, text); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.get_user_and_tags(IN p_email text, IN p_password text, IN p_type text)
    LANGUAGE sql
    AS $$
    -- Result 1: lấy user
    SELECT 
        u.*, true AS auth_ok
    FROM auth."user" u
    WHERE u.email = p_email
      AND (
          (lower(coalesce(p_type, '')) = 'local' AND auth.crypt(p_password, u."password") = u."password")
          OR (p_type IS NULL OR u."type" = p_type)
      );

    -- Result 2: lấy tag dựa trên id vừa lấy
    SELECT 
        t.user_id, t.function_tag_id, t.code, t.tag_name, t.tag_description,
        t.granted_at, t.expires_at, t.revoked_at
    FROM auth.v_user_function_tag_active t
    WHERE t.user_id IN (
        SELECT u.id
        FROM auth."user" u
        WHERE u.email = p_email
          AND (
              (lower(coalesce(p_type, '')) = 'local' AND auth.crypt(p_password, u."password") = u."password")
              OR (p_type IS NULL OR u."type" = p_type)
          )
    );
$$;


ALTER PROCEDURE auth.get_user_and_tags(IN p_email text, IN p_password text, IN p_type text) OWNER TO app_user;

--
-- TOC entry 447 (class 1255 OID 20233)
-- Name: get_user_auth_context(text, text, text); Type: FUNCTION; Schema: auth; Owner: app_user
--

CREATE FUNCTION auth.get_user_auth_context(p_email text, p_password text, p_type text) RETURNS TABLE(id integer, display_name character varying, is_privileged_account boolean, type character varying, status character, is_deleted character, created_date timestamp without time zone, created_user character varying, modified_date timestamp without time zone, modified_by character varying, email character varying, last_login timestamp without time zone, allow_public boolean, avatar_url character varying, setting jsonb, roles jsonb, components text[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    _user auth."user"%ROWTYPE;
BEGIN
    SELECT *
    INTO _user
    FROM auth.get_user(p_email, p_password, p_type)
    LIMIT 1;

    IF _user IS NULL THEN
        RAISE EXCEPTION 'User not found or invalid credentials'
        USING ERRCODE = 'P1001',
              DETAIL = format(
                  'email=%s, type=%s',
                  coalesce(p_email, '<null>'),
                  coalesce(p_type, '<null>')
              ),
              HINT = 'AUTH_INVALID_CREDENTIALS';
    END IF;

    RETURN QUERY
    SELECT *
    FROM auth.get_user_auth_context_by_email(_user.email, _user.type);
END;
$$;


ALTER FUNCTION auth.get_user_auth_context(p_email text, p_password text, p_type text) OWNER TO app_user;

--
-- TOC entry 328 (class 1255 OID 20234)
-- Name: get_user_auth_context_by_email(text, text); Type: FUNCTION; Schema: auth; Owner: app_user
--

CREATE FUNCTION auth.get_user_auth_context_by_email(p_email text, p_type text DEFAULT NULL::text) RETURNS TABLE(id integer, display_name character varying, is_privileged_account boolean, type character varying, status character, is_deleted character, created_date timestamp without time zone, created_user character varying, modified_date timestamp without time zone, modified_by character varying, email character varying, last_login timestamp without time zone, allow_public boolean, avatar_url character varying, setting jsonb, roles jsonb, components text[])
    LANGUAGE sql STABLE
    AS $$
WITH base_user AS (
    SELECT
        u.id,
        u.display_name,
        u.is_privileged_account,
        u.type,
        u.status,
        u.is_deleted,
        u.created_date,
        u.created_user,
        u.modified_date,
        u.modified_by,
        u.email,
        u.last_login,
        u.allow_public,
        u.avatar_url,
        u.setting
    FROM auth."user" u
    WHERE u.email = p_email
      AND (p_type IS NULL OR u.type = p_type)
    LIMIT 1
),
role_refs AS (
    SELECT DISTINCT ON (ur.role_name_ref)
        ur.role_name_ref AS name,
        ur.role_version AS version,
        ur.user_role_priority AS priority,
        ur.user_role_id
    FROM auth.v_user_role_active ur
    JOIN base_user bu
        ON bu.email = ur.user_email
    ORDER BY
        ur.role_name_ref,
        ur.user_role_priority DESC,
        ur.user_role_id DESC
),
component_refs AS (
    SELECT DISTINCT rc.component
    FROM auth.v_role_components_active rc
    JOIN role_refs rr
        ON rr.name = rc.role_name
)
SELECT
    bu.id,
    bu.display_name,
    bu.is_privileged_account,
    bu.type,
    bu.status,
    bu.is_deleted,
    bu.created_date,
    bu.created_user,
    bu.modified_date,
    bu.modified_by,
    bu.email,
    bu.last_login,
    bu.allow_public,
    bu.avatar_url,
    bu.setting,
    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'Name', rr.name,
                    'Version', rr.version,
                    'Priority', rr.priority
                )
                ORDER BY rr.priority DESC, rr.name ASC
            )
            FROM role_refs rr
        ),
        '[]'::jsonb
    ) AS roles,
    COALESCE(
        (
            SELECT array_agg(cr.component ORDER BY cr.component ASC)
            FROM component_refs cr
        ),
        ARRAY[]::text[]
    ) AS components
FROM base_user bu;
$$;


ALTER FUNCTION auth.get_user_auth_context_by_email(p_email text, p_type text) OWNER TO app_user;

--
-- TOC entry 421 (class 1255 OID 20235)
-- Name: l031_user_activate(bigint, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l031_user_activate(IN pv_id bigint, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE auth."user"
       SET status = 'A', is_deleted = 'N', modified_by = COALESCE(NULLIF(TRIM(sessioninfo_username), ''), 'system'),
           modified_date = CURRENT_TIMESTAMP
     WHERE id = pv_id::integer;
    IF NOT FOUND THEN RAISE EXCEPTION 'User with id "%" not found', pv_id; END IF;
END;
$$;


ALTER PROCEDURE auth.l031_user_activate(IN pv_id bigint, IN sessioninfo_username character varying) OWNER TO app_user;

--
-- TOC entry 459 (class 1255 OID 20236)
-- Name: l031_user_add(character varying, character varying, character varying, character varying, boolean, boolean, character varying, character varying, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l031_user_add(IN pv_display_name character varying, IN pv_email character varying, IN pv_password character varying, IN pv_type character varying, IN pv_is_privileged_account boolean, IN pv_allow_public boolean, IN pv_avatar_url character varying, IN pv_branchid character varying, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    CALL auth.l081_user_ins(
        pv_display_name, pv_email, pv_password, pv_type,
        pv_is_privileged_account, pv_allow_public, pv_avatar_url,
        '{}'::jsonb, sessioninfo_username, sessioninfo_username);

    UPDATE auth."user"
       SET branchid = NULLIF(TRIM(pv_branchid), ''),
           modified_by = COALESCE(NULLIF(TRIM(sessioninfo_username), ''), 'system'),
           modified_date = CURRENT_TIMESTAMP
     WHERE lower(email) = lower(TRIM(pv_email))
       AND lower(type) = lower(COALESCE(NULLIF(TRIM(pv_type), ''), 'local'));
END;
$$;


ALTER PROCEDURE auth.l031_user_add(IN pv_display_name character varying, IN pv_email character varying, IN pv_password character varying, IN pv_type character varying, IN pv_is_privileged_account boolean, IN pv_allow_public boolean, IN pv_avatar_url character varying, IN pv_branchid character varying, IN sessioninfo_username character varying) OWNER TO app_user;

