--
-- TOC entry 416 (class 1255 OID 20239)
-- Name: l031_user_reset_password(bigint, character varying, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l031_user_reset_password(IN pv_id bigint, IN pv_password character varying, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NULLIF(TRIM(pv_password), '') IS NULL THEN
        RAISE EXCEPTION 'New password is required';
    END IF;

    UPDATE auth."user"
       SET password = auth.crypt(pv_password, auth.gen_salt('bf')),
           modified_by = COALESCE(NULLIF(TRIM(sessioninfo_username), ''), 'system'),
           modified_date = CURRENT_TIMESTAMP
     WHERE id = pv_id::integer AND LOWER(COALESCE(type, 'local')) = 'local';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Local user with id "%" not found', pv_id;
    END IF;
END;
$$;


