--
-- TOC entry 404 (class 1255 OID 20240)
-- Name: l031_user_update(bigint, character varying, character varying, character varying, character, character, boolean, boolean, character varying, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l031_user_update(IN pv_id bigint, IN pv_display_name character varying, IN pv_email character varying, IN pv_type character varying, IN pv_status character, IN pv_is_deleted character, IN pv_is_privileged_account boolean, IN pv_allow_public boolean, IN pv_branchid character varying, IN sessioninfo_username character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    CALL auth.l081_user_upd(
        pv_id::integer, pv_display_name, pv_email, pv_type, pv_status, pv_is_deleted,
        pv_is_privileged_account, pv_allow_public, sessioninfo_username);

    UPDATE auth."user"
       SET branchid = NULLIF(TRIM(pv_branchid), ''),
           modified_by = COALESCE(NULLIF(TRIM(sessioninfo_username), ''), 'system'),
           modified_date = CURRENT_TIMESTAMP
     WHERE id = pv_id::integer;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User with id "%" not found', pv_id;
    END IF;
END;
$$;


