--
-- TOC entry 353 (class 1255 OID 20244)
-- Name: l034_policy_del(bigint, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l034_policy_del(IN pv_id bigint, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor    VARCHAR;
    v_name     VARCHAR;
    v_row_count INTEGER;
BEGIN
    v_actor := COALESCE(NULLIF(TRIM(COALESCE(_v_UserName, '')), ''), 'system');

    IF pv_id IS NULL THEN
        RAISE EXCEPTION 'Policy id is required';
    END IF;

    SELECT "name"
    INTO v_name
    FROM "auth"."policy"
    WHERE "id" = pv_id
      AND "is_delete" = FALSE;

    IF v_name IS NULL THEN
        RAISE EXCEPTION 'Active policy with id "%" not found', pv_id;
    END IF;

    UPDATE "auth"."policy"
    SET "is_delete" = TRUE,
        "modified_by" = v_actor,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "id" = pv_id
      AND "is_delete" = FALSE;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    IF v_row_count = 0 THEN
        RAISE EXCEPTION 'Active policy with id "%" not found', pv_id;
    END IF;

    UPDATE "auth"."role" AS "r"
    SET "version" = "r"."version" + 1,
        "modified_by" = v_actor,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "r"."is_delete" = FALSE
      AND EXISTS (
          SELECT 1
          FROM "auth"."role_policy" AS "rp"
          WHERE "rp"."role_name" = "r"."name"
            AND "rp"."policy_name" = v_name
            AND "rp"."is_delete" = FALSE
      );

EXCEPTION
    WHEN raise_exception THEN
        RAISE;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to delete policy: %', SQLERRM;
END;
$$;


ALTER PROCEDURE auth.l034_policy_del(IN pv_id bigint, IN _v_username character varying) OWNER TO app_user;

--
-- TOC entry 424 (class 1255 OID 20245)
-- Name: l034_policy_ins(character varying, jsonb, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l034_policy_ins(IN pv_name character varying, IN pv_content jsonb, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor VARCHAR;
    v_name  VARCHAR;
BEGIN
    v_actor := COALESCE(NULLIF(TRIM(COALESCE(_v_UserName, '')), ''), 'system');
    v_name := TRIM(COALESCE(pv_name, ''));

    IF v_name = '' THEN
        RAISE EXCEPTION 'Policy name is required';
    END IF;

    IF pv_content IS NULL THEN
        RAISE EXCEPTION 'Policy content is required';
    END IF;

    IF jsonb_typeof(pv_content) <> 'object' THEN
        RAISE EXCEPTION 'Policy content must be a JSON object';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM "auth"."policy"
        WHERE "name" = v_name
          AND "is_delete" = FALSE
    ) THEN
        RAISE EXCEPTION 'Active policy "%" already exists', v_name;
    END IF;

    INSERT INTO "auth"."policy" (
        "name",
        "is_delete",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date",
        "content"
    )
    VALUES (
        v_name,
        FALSE,
        v_actor,
        CURRENT_TIMESTAMP,
        v_actor,
        CURRENT_TIMESTAMP,
        pv_content
    );

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Active policy "%" already exists', v_name;
    WHEN raise_exception THEN
        RAISE;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to insert policy: %', SQLERRM;
END;
$$;


ALTER PROCEDURE auth.l034_policy_ins(IN pv_name character varying, IN pv_content jsonb, IN _v_username character varying) OWNER TO app_user;

--
-- TOC entry 382 (class 1255 OID 20246)
-- Name: l034_policy_upd(bigint, jsonb, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l034_policy_upd(IN pv_id bigint, IN pv_content jsonb, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor    VARCHAR;
    v_name     VARCHAR;
    v_created_by VARCHAR;
    v_created_date TIMESTAMP;
    v_row_count INTEGER;
BEGIN
    v_actor := COALESCE(NULLIF(TRIM(COALESCE(_v_UserName, '')), ''), 'system');

    IF pv_id IS NULL THEN
        RAISE EXCEPTION 'Policy id is required';
    END IF;

    IF pv_content IS NULL THEN
        RAISE EXCEPTION 'Policy content is required';
    END IF;

    IF jsonb_typeof(pv_content) <> 'object' THEN
        RAISE EXCEPTION 'Policy content must be a JSON object';
    END IF;

    SELECT "name", "created_by", "created_date"
    INTO v_name, v_created_by, v_created_date
    FROM "auth"."policy"
    WHERE "id" = pv_id
      AND "is_delete" = FALSE;

    IF v_name IS NULL THEN
        RAISE EXCEPTION 'Active policy with id "%" not found', pv_id;
    END IF;

    UPDATE "auth"."policy"
    SET "is_delete" = TRUE,
        "modified_by" = v_actor,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "id" = pv_id
      AND "is_delete" = FALSE;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    IF v_row_count = 0 THEN
        RAISE EXCEPTION 'Active policy with id "%" not found', pv_id;
    END IF;

    INSERT INTO "auth"."policy" (
        "name",
        "is_delete",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date",
        "content"
    )
    VALUES (
        v_name,
        FALSE,
        COALESCE(v_created_by, v_actor),
        COALESCE(v_created_date, CURRENT_TIMESTAMP),
        v_actor,
        CURRENT_TIMESTAMP,
        pv_content
    );

    UPDATE "auth"."role" AS "r"
    SET "version" = "r"."version" + 1,
        "modified_by" = v_actor,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "r"."is_delete" = FALSE
      AND EXISTS (
          SELECT 1
          FROM "auth"."role_policy" AS "rp"
          WHERE "rp"."role_name" = "r"."name"
            AND "rp"."policy_name" = v_name
            AND "rp"."is_delete" = FALSE
      );

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Active policy "%" already exists', v_name;
    WHEN raise_exception THEN
        RAISE;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to update policy: %', SQLERRM;
END;
$$;


