--
-- TOC entry 318 (class 1255 OID 20248)
-- Name: l035_role_policy_ins(character varying, character varying, integer, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l035_role_policy_ins(IN pv_role_name character varying, IN pv_policy_name character varying, IN pv_priority integer DEFAULT 100, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor       VARCHAR;
    v_role_name   VARCHAR;
    v_policy_name VARCHAR;
    v_priority    INTEGER;
BEGIN
    v_actor := COALESCE(NULLIF(TRIM(COALESCE(_v_UserName, '')), ''), 'system');
    v_role_name := TRIM(COALESCE(pv_role_name, ''));
    v_policy_name := TRIM(COALESCE(pv_policy_name, ''));
    v_priority := COALESCE(pv_priority, 100);

    IF v_role_name = '' THEN
        RAISE EXCEPTION 'Role name is required';
    END IF;

    IF v_policy_name = '' THEN
        RAISE EXCEPTION 'Policy name is required';
    END IF;

    IF v_priority <= 0 THEN
        RAISE EXCEPTION 'Priority must be greater than 0';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM "auth"."role"
        WHERE "name" = v_role_name
          AND "is_delete" = FALSE
    ) THEN
        RAISE EXCEPTION 'Active role "%" was not found', v_role_name;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM "auth"."policy"
        WHERE "name" = v_policy_name
          AND "is_delete" = FALSE
    ) THEN
        RAISE EXCEPTION 'Active policy "%" was not found', v_policy_name;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM "auth"."role_policy"
        WHERE "role_name" = v_role_name
          AND "policy_name" = v_policy_name
          AND "is_delete" = FALSE
    ) THEN
        RAISE EXCEPTION 'Active role-policy mapping "%" - "%" already exists', v_role_name, v_policy_name;
    END IF;

    INSERT INTO "auth"."role_policy" (
        "role_name",
        "policy_name",
        "is_delete",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date",
        "priority"
    )
    VALUES (
        v_role_name,
        v_policy_name,
        FALSE,
        v_actor,
        CURRENT_TIMESTAMP,
        v_actor,
        CURRENT_TIMESTAMP,
        v_priority
    );

    UPDATE "auth"."role"
    SET "version" = "version" + 1,
        "modified_by" = v_actor,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "name" = v_role_name
      AND "is_delete" = FALSE;

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Active role-policy mapping "%" - "%" already exists', v_role_name, v_policy_name;
    WHEN raise_exception THEN
        RAISE;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to insert role_policy: %', SQLERRM;
END;
$$;


ALTER PROCEDURE auth.l035_role_policy_ins(IN pv_role_name character varying, IN pv_policy_name character varying, IN pv_priority integer, IN _v_username character varying) OWNER TO app_user;

--
-- TOC entry 414 (class 1255 OID 20249)
-- Name: l035_role_policy_upd(bigint, integer, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l035_role_policy_upd(IN pv_id bigint, IN pv_priority integer, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor     VARCHAR;
    v_role_name VARCHAR;
    v_row_count INTEGER;
BEGIN
    v_actor := COALESCE(NULLIF(TRIM(COALESCE(_v_UserName, '')), ''), 'system');

    IF pv_id IS NULL THEN
        RAISE EXCEPTION 'Role-policy mapping id is required';
    END IF;

    IF pv_priority IS NULL OR pv_priority <= 0 THEN
        RAISE EXCEPTION 'Priority must be greater than 0';
    END IF;

    SELECT "role_name"
    INTO v_role_name
    FROM "auth"."role_policy"
    WHERE "id" = pv_id
      AND "is_delete" = FALSE;

    IF v_role_name IS NULL THEN
        RAISE EXCEPTION 'Active role-policy mapping with id "%" not found', pv_id;
    END IF;

    UPDATE "auth"."role_policy"
    SET "priority" = pv_priority,
        "modified_by" = v_actor,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "id" = pv_id
      AND "is_delete" = FALSE;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    IF v_row_count = 0 THEN
        RAISE EXCEPTION 'Active role-policy mapping with id "%" not found', pv_id;
    END IF;

    UPDATE "auth"."role"
    SET "version" = "version" + 1,
        "modified_by" = v_actor,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "name" = v_role_name
      AND "is_delete" = FALSE;

EXCEPTION
    WHEN raise_exception THEN
        RAISE;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to update role_policy: %', SQLERRM;
END;
$$;


