-- Name: l081_auth_user_reset_all_local_passwords_dev(character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l081_auth_user_reset_all_local_passwords_dev(IN pv_new_password character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row_count INTEGER;
BEGIN
    -- WARNING: This procedure is for development/testing only
    -- It resets all local user passwords to the same value
    
    IF trim(coalesce(pv_new_password, '')) = '' THEN
        RAISE EXCEPTION 'New password cannot be empty';
    END IF;

    UPDATE auth."user"
    SET password      = auth.crypt(pv_new_password, auth.gen_salt('bf')),
        modified_by   = 'system',
        modified_date = CURRENT_TIMESTAMP
    WHERE type = 'local'
      AND is_deleted = 'N';

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    RAISE NOTICE 'Reset passwords for % local users', v_row_count;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to reset passwords: %', SQLERRM;
END;
$$;


