--
-- TOC entry 458 (class 1255 OID 20264)
-- Name: l081_user_ins(character varying, character varying, character varying, character varying, boolean, boolean, character varying, jsonb, character varying, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l081_user_ins(IN pv_display_name character varying, IN pv_email character varying, IN pv_password character varying DEFAULT NULL::character varying, IN pv_type character varying DEFAULT 'local'::character varying, IN pv_is_privileged_account boolean DEFAULT false, IN pv_allow_public boolean DEFAULT false, IN pv_avatar_url character varying DEFAULT NULL::character varying, IN pv_setting jsonb DEFAULT NULL::jsonb, IN _v_username character varying DEFAULT NULL::character varying, IN _v_email character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_email         VARCHAR;
    v_type          VARCHAR;
    v_actor         VARCHAR;
    v_display_name  VARCHAR;
BEGIN
    v_email := lower(trim(coalesce(pv_email, '')));
    v_type := lower(trim(coalesce(pv_type, 'local')));
    v_actor := coalesce(nullif(trim(coalesce(_v_UserName, '')), ''), nullif(trim(coalesce(_v_Email, '')), ''), 'system');
    v_display_name := coalesce(nullif(trim(coalesce(pv_display_name, '')), ''), split_part(v_email, '@', 1));

    IF v_email = '' THEN
        RAISE EXCEPTION 'Email is required';
    END IF;

    IF v_type = '' THEN
        v_type := 'local';
    END IF;

    IF v_type = 'local' AND trim(coalesce(pv_password, '')) = '' THEN
        RAISE EXCEPTION 'Password is required for local user';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM auth."user" u
        WHERE lower(coalesce(u.email, '')) = v_email
          AND lower(coalesce(u.type, '')) = v_type
    ) THEN
        RAISE EXCEPTION 'User with email "%" and type "%" already exists', v_email, v_type;
    END IF;

    INSERT INTO auth."user" (
        display_name,
        password,
        is_privileged_account,
        type,
        status,
        is_deleted,
        created_date,
        created_user,
        modified_date,
        modified_by,
        email,
        last_login,
        allow_public,
        avatar_url,
        setting
    )
    VALUES (
        v_display_name,
        CASE
            WHEN v_type = 'local' THEN auth.crypt(pv_password, auth.gen_salt('bf'))
            ELSE NULL
        END,
        coalesce(pv_is_privileged_account, FALSE),
        v_type,
        'A',
        'N',
        CURRENT_TIMESTAMP,
        v_actor,
        CURRENT_TIMESTAMP,
        v_actor,
        v_email,
        NULL,
        coalesce(pv_allow_public, FALSE),
        nullif(trim(coalesce(pv_avatar_url, '')), ''),
        coalesce(pv_setting, '{}'::jsonb)
    );
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'User with email "%" and type "%" already exists', v_email, v_type;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to insert user: %', SQLERRM;
END;
$$;


