CREATE PROCEDURE auth.l082_auth_role_ins(IN pv_name character varying, IN pv_description text DEFAULT NULL::text, IN pv_default_data_scope text DEFAULT NULL::text, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor VARCHAR;
