--
-- TOC entry 341 (class 1255 OID 20268)
-- Name: l082_auth_role_upd(bigint, text, text, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l082_auth_role_upd(IN pv_id bigint, IN pv_description text, IN pv_default_data_scope text, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor              VARCHAR;
    v_old_name           VARCHAR;
    v_old_version        INTEGER;
    v_old_data_scope     TEXT;
BEGIN
    v_actor := coalesce(nullif(trim(coalesce(_v_UserName, '')), ''), 'system');

    -- Lấy dữ liệu hiện tại
    SELECT name, version, default_data_scope
    INTO v_old_name, v_old_version, v_old_data_scope
    FROM auth."role"
    WHERE id = pv_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Role with id "%" not found', pv_id;
    END IF;

    -- Nếu default_data_scope thay đổi → append-only: soft delete cũ + insert mới
    IF coalesce(v_old_data_scope, '') IS DISTINCT FROM coalesce(pv_default_data_scope, '') THEN
        -- Soft delete row cũ
        UPDATE auth."role"
        SET is_delete     = true,
            modified_by   = v_actor,
            modified_date = CURRENT_TIMESTAMP
        WHERE id = pv_id;

        -- Insert row mới cùng name, version + 1
        INSERT INTO auth."role" (
            name, version, is_delete, description, default_data_scope,
            created_date, created_by, modified_date, modified_by
        )
        VALUES (
            v_old_name,
            v_old_version + 1,
            false,
            pv_description,
            pv_default_data_scope,
            CURRENT_TIMESTAMP,
            v_actor,
            CURRENT_TIMESTAMP,
            v_actor
        );
    ELSE
        -- Không thay đổi auth-affecting data → update trực tiếp
        UPDATE auth."role"
        SET description        = pv_description,
            default_data_scope = pv_default_data_scope,
            modified_by        = v_actor,
            modified_date      = CURRENT_TIMESTAMP
        WHERE id = pv_id;
    END IF;

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Role with name "%" already exists (active)', v_old_name;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to update role: %', SQLERRM;
END;
$$;


ALTER PROCEDURE auth.l082_auth_role_upd(IN pv_id bigint, IN pv_description text, IN pv_default_data_scope text, IN _v_username character varying) OWNER TO app_user;

