--
-- TOC entry 464 (class 1255 OID 20270)
-- Name: l083_auth_user_role_ins(character varying, character varying, integer, text, timestamp without time zone, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l083_auth_user_role_ins(IN pv_user_email character varying, IN pv_role_name character varying, IN pv_priority integer DEFAULT 100, IN pv_note text DEFAULT NULL::text, IN pv_expires_at timestamp without time zone DEFAULT NULL::timestamp without time zone, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor      VARCHAR;
    v_user_email VARCHAR;
    v_role_name  VARCHAR;
BEGIN
    v_user_email := trim(coalesce(pv_user_email, ''));
    v_role_name  := trim(coalesce(pv_role_name, ''));
    v_actor      := coalesce(nullif(trim(coalesce(_v_UserName, '')), ''), 'system');

    IF v_user_email = '' THEN
        RAISE EXCEPTION 'User email is required';
    END IF;

    IF v_role_name = '' THEN
        RAISE EXCEPTION 'Role name is required';
    END IF;

    IF coalesce(pv_priority, 100) <= 0 THEN
        RAISE EXCEPTION 'Priority must be greater than 0';
    END IF;

    INSERT INTO auth.user_role (
        user_email,
        role_name,
        priority,
        note,
        is_delete,
        expires_at,
        created_by,
        created_date,
        modified_by,
        modified_date
    )
    VALUES (
        v_user_email,
        v_role_name,
        coalesce(pv_priority, 100),
        pv_note,
        false,
        pv_expires_at,
        v_actor,
        CURRENT_TIMESTAMP,
        v_actor,
        CURRENT_TIMESTAMP
    );

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'User role assignment for user "%" with role "%" already exists', v_user_email, v_role_name;
    WHEN exclusion_violation THEN
        RAISE EXCEPTION 'User role assignment for user "%" with role "%" overlaps with an existing active assignment', v_user_email, v_role_name;
    WHEN check_violation THEN
        RAISE EXCEPTION 'Priority must be greater than 0';
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to insert user role assignment: %', SQLERRM;
END;
$$;


ALTER PROCEDURE auth.l083_auth_user_role_ins(IN pv_user_email character varying, IN pv_role_name character varying, IN pv_priority integer, IN pv_note text, IN pv_expires_at timestamp without time zone, IN _v_username character varying) OWNER TO app_user;

