-- TOC entry 376 (class 1255 OID 20271)
-- Name: l083_auth_user_role_upd(bigint, integer, text, timestamp without time zone, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l083_auth_user_role_upd(IN pv_id bigint, IN pv_priority integer, IN pv_note text, IN pv_expires_at timestamp without time zone, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor          VARCHAR;
    v_old_user_email VARCHAR;
    v_old_role_name  VARCHAR;
BEGIN
    v_actor := coalesce(nullif(trim(coalesce(_v_UserName, '')), ''), 'system');

    IF coalesce(pv_priority, 0) <= 0 THEN
        RAISE EXCEPTION 'Priority must be greater than 0';
    END IF;

    -- Lấy dữ liệu hiện tại (chỉ row active)
    SELECT user_email, role_name
    INTO v_old_user_email, v_old_role_name
    FROM auth.user_role
    WHERE id = pv_id
      AND is_delete = false;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User role assignment with id "%" not found', pv_id;
    END IF;

    -- Soft delete row cũ
    UPDATE auth.user_role
    SET is_delete     = true,
        modified_by   = v_actor,
        modified_date = CURRENT_TIMESTAMP
    WHERE id = pv_id;

    -- Insert row mới cùng user_email + role_name
    INSERT INTO auth.user_role (
        user_email,
        role_name,
        priority,
        note,
        is_delete,
        expires_at,
        created_by,
        created_date,
        modified_by,
        modified_date
    )
    VALUES (
        v_old_user_email,
        v_old_role_name,
        pv_priority,
        pv_note,
        false,
        pv_expires_at,
        v_actor,
        CURRENT_TIMESTAMP,
        v_actor,
        CURRENT_TIMESTAMP
    );

EXCEPTION
    WHEN exclusion_violation THEN
        RAISE EXCEPTION 'User role assignment for user "%" with role "%" overlaps with an existing active assignment', v_old_user_email, v_old_role_name;
    WHEN check_violation THEN
        RAISE EXCEPTION 'Priority must be greater than 0';
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to update user role assignment: %', SQLERRM;
END;
$$;


