--
-- TOC entry 426 (class 1255 OID 20272)
-- Name: l086_role_component_del(bigint, character varying); Type: PROCEDURE; Schema: auth; Owner: app_user
--

CREATE PROCEDURE auth.l086_role_component_del(IN pv_id bigint, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row_count INTEGER;
    v_role_name VARCHAR;
    v_actor     VARCHAR;
BEGIN
    v_actor := coalesce(nullif(trim(coalesce(_v_UserName, '')), ''), 'system');

    -- 1. Lấy role_name trước khi soft delete
    SELECT role_name INTO v_role_name
    FROM auth.role_component
    WHERE id = pv_id AND is_delete = false;

    IF v_role_name IS NULL THEN
        RAISE EXCEPTION 'Role component with id "%" not found', pv_id;
    END IF;

    -- 2. Soft delete với audit
    UPDATE auth.role_component
    SET is_delete      = true,
        modified_by    = v_actor,
        modified_date  = CURRENT_TIMESTAMP
    WHERE id = pv_id;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    IF v_row_count = 0 THEN
        RAISE EXCEPTION 'Role component with id "%" not found', pv_id;
    END IF;

    -- 3. Bump version của role bị ảnh hưởng
    UPDATE auth."role"
    SET version       = version + 1,
        modified_by   = v_actor,
        modified_date = CURRENT_TIMESTAMP
    WHERE name = v_role_name
      AND is_delete = false;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to delete role_component: %', SQLERRM;
END;
$$;


