    SET version       = version + 1,
        modified_by   = v_actor,
        modified_date = CURRENT_TIMESTAMP
    WHERE name = v_role_name
      AND is_delete = false;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to update role_component: %', SQLERRM;
END;
$$;


ALTER PROCEDURE auth.l086_role_component_upd(IN pv_id bigint, IN _v_username character varying) OWNER TO app_user;

--
-- TOC entry 388 (class 1255 OID 20275)
-- Name: dashboard_module_dup(character varying, character varying, character varying); Type: PROCEDURE; Schema: core; Owner: app_user
--

CREATE PROCEDURE core.dashboard_module_dup(IN pv_source_mod_id character varying, IN pv_new_mod_id character varying, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_source_mod_id varchar := upper(trim(coalesce(pv_source_mod_id, '')));
    v_new_mod_id varchar := upper(trim(coalesce(pv_new_mod_id, '')));
    v_user varchar := coalesce(nullif(trim(_v_UserName), ''), 'system');
    v_source record;
BEGIN
    IF v_source_mod_id !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid source dashboard module id: %', pv_source_mod_id
            USING ERRCODE = '22023';
    END IF;

    IF v_new_mod_id !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid new dashboard module id: %', pv_new_mod_id
            USING ERRCODE = '22023';
    END IF;

    SELECT *
    INTO v_source
    FROM "core"."def_mod"
    WHERE "mod_id" = v_source_mod_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Source dashboard module % not found', v_source_mod_id
            USING ERRCODE = '02000';
    END IF;

    IF EXISTS (SELECT 1 FROM "core"."def_mod" WHERE "mod_id" = v_new_mod_id) THEN
        RAISE EXCEPTION 'Dashboard module % already exists', v_new_mod_id
            USING ERRCODE = '23505';
    END IF;

    INSERT INTO "core"."def_mod"
    (
        "mod_id",
        "mod_name",
        "config",
        "config_ui",
        "language",
        "metadata",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date"
    )
    VALUES
    (
        v_new_mod_id,
        v_source."mod_name",
        v_source."config",
        v_source."config_ui",
        v_source."language",
        v_source."metadata",
        v_user,
        CURRENT_TIMESTAMP,
        v_user,
        CURRENT_TIMESTAMP
    );
END;
$_$;


ALTER PROCEDURE core.dashboard_module_dup(IN pv_source_mod_id character varying, IN pv_new_mod_id character varying, IN _v_username character varying) OWNER TO app_user;

--
-- TOC entry 453 (class 1255 OID 20276)
-- Name: dashboard_module_ins(character varying, character varying, character varying, jsonb, character varying, boolean, boolean, character varying, text, text, jsonb, text, text, text, text, boolean, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying); Type: PROCEDURE; Schema: core; Owner: app_user
--

CREATE PROCEDURE core.dashboard_module_ins(IN pv_mod_id character varying, IN pv_mod_name_en character varying, IN pv_mod_name_vi character varying, IN pv_data_sources jsonb, IN pv_default_mode character varying DEFAULT 'viewerOnly'::character varying, IN pv_allow_designer boolean DEFAULT true, IN pv_show_toolbar boolean DEFAULT true, IN pv_height character varying DEFAULT '100%'::character varying, IN pv_description_en text DEFAULT NULL::text, IN pv_description_vi text DEFAULT NULL::text, IN pv_tags jsonb DEFAULT '[]'::jsonb, IN pv_help_markdown_en text DEFAULT NULL::text, IN pv_help_markdown_vi text DEFAULT NULL::text, IN pv_ai_screen_purpose_en text DEFAULT NULL::text, IN pv_ai_screen_purpose_vi text DEFAULT NULL::text, IN pv_publish_menu boolean DEFAULT false, IN pv_menu_component character varying DEFAULT NULL::character varying, IN pv_menu_id character varying DEFAULT NULL::character varying, IN pv_owner_menu_id character varying DEFAULT NULL::character varying, IN pv_menu_icon character varying DEFAULT 'chart'::character varying, IN pv_menu_position numeric DEFAULT 0, IN pv_menu_name_en character varying DEFAULT NULL::character varying, IN pv_menu_name_vi character varying DEFAULT NULL::character varying, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_mod_id varchar := upper(trim(coalesce(pv_mod_id, '')));
    v_user varchar := coalesce(nullif(trim(_v_UserName), ''), 'system');
    v_missing_sources text;
    v_layout_xml text;
    v_config jsonb;
    v_config_ui jsonb;
    v_language jsonb;
    v_metadata jsonb;
    v_existing_menu_module varchar;
BEGIN
    IF v_mod_id !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid dashboard module id: %', pv_mod_id
            USING ERRCODE = '22023';
    END IF;

    IF EXISTS (SELECT 1 FROM "core"."def_mod" WHERE "mod_id" = v_mod_id) THEN
        RAISE EXCEPTION 'Dashboard module % already exists', v_mod_id
            USING ERRCODE = '23505';
    END IF;

    IF pv_data_sources IS NULL
       OR jsonb_typeof(pv_data_sources) <> 'array'
       OR jsonb_array_length(pv_data_sources) = 0 THEN
        RAISE EXCEPTION 'At least one dashboard data source is required'
            USING ERRCODE = '22023';
    END IF;

    SELECT string_agg(src."value", ', ')
    INTO v_missing_sources
    FROM jsonb_array_elements_text(pv_data_sources) AS src("value")
    WHERE NOT EXISTS (
        SELECT 1
        FROM "core"."def_source" ds
        WHERE ds."source_name" = src."value"
    );

    IF v_missing_sources IS NOT NULL THEN
        RAISE EXCEPTION 'Unknown dashboard data source(s): %', v_missing_sources
            USING ERRCODE = '22023';
    END IF;

    IF jsonb_typeof(coalesce(pv_tags, '[]'::jsonb)) <> 'array' THEN
        RAISE EXCEPTION 'Tags must be a JSON array'
            USING ERRCODE = '22023';
    END IF;

    IF pv_publish_menu THEN
        IF nullif(trim(coalesce(pv_menu_component, '')), '') IS NULL
           OR nullif(trim(coalesce(pv_menu_id, '')), '') IS NULL THEN
            RAISE EXCEPTION 'Menu component and menu id are required when publish menu is enabled'
                USING ERRCODE = '22023';
        END IF;

        SELECT "module_id"
        INTO v_existing_menu_module
        FROM "core"."def_menu"
        WHERE "component" = pv_menu_component
          AND "menu_id" = pv_menu_id;

        IF v_existing_menu_module IS NOT NULL AND v_existing_menu_module <> v_mod_id THEN
            RAISE EXCEPTION 'Menu %.% already belongs to module %',
                pv_menu_component, pv_menu_id, v_existing_menu_module
                USING ERRCODE = '23505';
        END IF;
    END IF;

    v_layout_xml := format($xml$<?xml version="1.0" encoding="utf-8"?>
<Dashboard RequestParameters="false">
  <Title Text="%s" />
</Dashboard>
$xml$, v_mod_id);

    v_config := jsonb_build_object(
        'schemaVersion', 1,
        'engine', 'devexpress-dashboard',
        'dataSources', pv_data_sources,
        'features', jsonb_build_object(
            'allowCustomSql', false,
            'allowCreateNewJsonConnection', false
        )
    );

    v_config_ui := jsonb_build_object(
        'schemaVersion', 1,
        'defaultMode', coalesce(nullif(trim(pv_default_mode), ''), 'viewerOnly'),
        'allowDesigner', coalesce(pv_allow_designer, true),
        'showToolbar', coalesce(pv_show_toolbar, true),
        'height', coalesce(nullif(trim(pv_height), ''), '100%'),
        'layoutXml', v_layout_xml
    );

    v_language := jsonb_build_object(
        'en', jsonb_build_object(
            'Module$Name', pv_mod_name_en,
            'Page$Title', pv_mod_name_en
        ),
        'vi', jsonb_build_object(
            'Module$Name', pv_mod_name_vi,
            'Page$Title', pv_mod_name_vi
        )
    );

    v_metadata := jsonb_build_object(
        'schemaVersion', 1,
        'description', jsonb_build_object(
            'en', coalesce(pv_description_en, ''),
            'vi', coalesce(pv_description_vi, '')
        ),
        'tags', coalesce(pv_tags, '[]'::jsonb),
        'help', jsonb_build_object(
            'en', jsonb_build_object(
                'format', 'markdown',
                'markdown', coalesce(pv_help_markdown_en, ''),
                'text', coalesce(pv_help_markdown_en, '')
            ),
            'vi', jsonb_build_object(
                'format', 'markdown',
                'markdown', coalesce(pv_help_markdown_vi, ''),
                'text', coalesce(pv_help_markdown_vi, '')
            )
        ),
        'ai', jsonb_build_object(
            'screenPurpose', jsonb_build_object(
                'en', coalesce(pv_ai_screen_purpose_en, ''),
                'vi', coalesce(pv_ai_screen_purpose_vi, '')
            )
        )
    );

    INSERT INTO "core"."def_mod"
    (
        "mod_id",
        "mod_name",
        "config",
        "config_ui",
        "language",
        "metadata",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date"
    )
    VALUES
    (
        v_mod_id,
        pv_mod_name_en,
        v_config,
        v_config_ui,
        v_language,
        v_metadata,
        v_user,
        CURRENT_TIMESTAMP,
        v_user,
        CURRENT_TIMESTAMP
    );

    IF pv_publish_menu THEN
        INSERT INTO "core"."def_menu"
        (
            "component",
            "menu_id",
            "owner_menu_id",
            "icon",
            "module_id",
            "position",
            "param",
            "language"
        )
        VALUES
        (
            pv_menu_component,
            pv_menu_id,
            nullif(trim(coalesce(pv_owner_menu_id, '')), ''),
            coalesce(nullif(trim(pv_menu_icon), ''), 'chart'),
            v_mod_id,
            coalesce(pv_menu_position, 0),
            NULL,
            jsonb_build_object(
                'en', jsonb_build_object('Name', coalesce(nullif(trim(pv_menu_name_en), ''), pv_mod_name_en)),
                'vi', jsonb_build_object('Name', coalesce(nullif(trim(pv_menu_name_vi), ''), pv_mod_name_vi))
            )
        )
        ON CONFLICT ("component", "menu_id") DO UPDATE
        SET
            "owner_menu_id" = EXCLUDED."owner_menu_id",
            "icon" = EXCLUDED."icon",
            "module_id" = EXCLUDED."module_id",
            "position" = EXCLUDED."position",
            "param" = EXCLUDED."param",
            "language" = EXCLUDED."language";
    END IF;
END;
$_$;


ALTER PROCEDURE core.dashboard_module_ins(IN pv_mod_id character varying, IN pv_mod_name_en character varying, IN pv_mod_name_vi character varying, IN pv_data_sources jsonb, IN pv_default_mode character varying, IN pv_allow_designer boolean, IN pv_show_toolbar boolean, IN pv_height character varying, IN pv_description_en text, IN pv_description_vi text, IN pv_tags jsonb, IN pv_help_markdown_en text, IN pv_help_markdown_vi text, IN pv_ai_screen_purpose_en text, IN pv_ai_screen_purpose_vi text, IN pv_publish_menu boolean, IN pv_menu_component character varying, IN pv_menu_id character varying, IN pv_owner_menu_id character varying, IN pv_menu_icon character varying, IN pv_menu_position numeric, IN pv_menu_name_en character varying, IN pv_menu_name_vi character varying, IN _v_username character varying) OWNER TO app_user;

