            'screenPurpose', jsonb_build_object(
                'en', coalesce(pv_ai_screen_purpose_en, ''),
                'vi', coalesce(pv_ai_screen_purpose_vi, '')
            )
        )
    );

    UPDATE "core"."def_mod"
    SET
        "mod_name" = pv_mod_name_en,
        "config" = v_config,
        "config_ui" = v_config_ui,
        "language" = v_language,
        "metadata" = v_metadata,
        "modified_by" = v_user,
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "mod_id" = v_mod_id;

    IF pv_publish_menu THEN
        DELETE FROM "core"."def_menu"
        WHERE "module_id" = v_mod_id
