--
-- TOC entry 417 (class 1255 OID 20280)
-- Name: get_core_data_json(text); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.get_core_data_json(n_table_name text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
-- *****************************************************************
-- Name:
--   core.get_core_data_json
--
-- Description:
--   Returns core reference data as a JSON document.
--   The function accepts a comma-separated list of table names,
--   dynamically queries each table under schema "core",
--   and aggregates the result into a single JSON object.
--
--   Each table is returned as a JSON array with the key:
--     "List<TableName>"
--
--   The final output structure is wrapped with a root object "Core".
--
-- Input Parameters:
--   n_table_name TEXT
--     - Comma-separated list of table names
--     - Example: 'User,Role,Permission'
--
-- Output:
--   JSONB
--     - Root object: "Core"
--     - Fields:
--         CREATE_DATE   : timestamp when the JSON is generated
--         List<Table>   : JSON array of rows from each table
--
-- Error Conditions Raised:
--   - UndefinedTable:    If a table name does not exist in schema "core"
--   - InsufficientPrivilege: If caller has no SELECT permission
--
-- Security Considerations:
--   - Dynamic SQL is used with identifier-safe formatting (%I)
--   - Prevents SQL injection on table names
--
-- Performance Notes:
--   - One SQL query is executed per table
--   - Intended for small to medium-sized reference tables
--   - Not recommended for large transactional tables
--
-- *****************************************************************
DECLARE
    v_table text;
    v_result jsonb := jsonb_build_object(
        'CREATE_DATE', now()
    );
    v_sql text;
    v_table_data jsonb;
BEGIN
    /*
        Loop qua danh sách bảng truyền vào:
        ví dụ: 'User,Role,Permission'
    */
    FOR v_table IN
        SELECT trim(value)
        FROM unnest(string_to_array(n_table_name, ',')) AS value
        WHERE value IS NOT NULL AND length(trim(value)) > 0
    LOOP
        /*
            Build SQL:
            SELECT jsonb_agg(row_to_json(t))
            FROM core.<table> t
        */
        v_sql := format(
            'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
             FROM core.%I t',
            v_table
        );

        EXECUTE v_sql INTO v_table_data;

        /*
            Add vào object kết quả:
            "List<TableName>" : [...]
        */
        v_result := v_result || jsonb_build_object(
            v_table,
            v_table_data
        );
    END LOOP;

    /*
        Bọc root "Core"
    */
    RETURN jsonb_build_object('Core', v_result);
END;
$$;


ALTER FUNCTION core.get_core_data_json(n_table_name text) OWNER TO app_user;

--
-- TOC entry 379 (class 1255 OID 20281)
-- Name: l001_def_source_del(character varying); Type: PROCEDURE; Schema: core; Owner: app_user
--

CREATE PROCEDURE core.l001_def_source_del(IN pv_source_name character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row_count INTEGER;
BEGIN
    DELETE FROM core.def_source
    WHERE source_name = pv_source_name;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    IF v_row_count = 0 THEN
        RAISE EXCEPTION 'Data source with name "%" not found', pv_source_name;
    END IF;

EXCEPTION
    WHEN foreign_key_violation THEN
        RAISE EXCEPTION 'Cannot delete: data source "%" is referenced by other records', pv_source_name;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to delete data source: %', SQLERRM;
END;
$$;


ALTER PROCEDURE core.l001_def_source_del(IN pv_source_name character varying) OWNER TO app_user;

