    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row_count INTEGER;
BEGIN
    DELETE FROM core.def_menu
    WHERE component = pv_component
      AND menu_id   = pv_menu_id;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    IF v_row_count = 0 THEN
        RAISE EXCEPTION 'Record with component="%" menu_id="%" not found', pv_component, pv_menu_id;
    END IF;

EXCEPTION
    WHEN foreign_key_violation THEN
        RAISE EXCEPTION 'Cannot delete: record with component="%" menu_id="%" is referenced by other records', pv_component, pv_menu_id;
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to delete: %', SQLERRM;
END;
$$;


