--
-- TOC entry 419 (class 1255 OID 20300)
-- Name: l007_def_mod_upd(character varying, character varying, jsonb, jsonb, jsonb, jsonb, character varying, character varying, character varying, timestamp without time zone, character varying); Type: PROCEDURE; Schema: core; Owner: app_user
--

CREATE PROCEDURE core.l007_def_mod_upd(IN pv_mod_id character varying, IN pv_mod_name character varying DEFAULT NULL::character varying, IN pv_config jsonb DEFAULT NULL::jsonb, IN pv_config_ui jsonb DEFAULT NULL::jsonb, IN pv_language jsonb DEFAULT NULL::jsonb, IN pv_metadata jsonb DEFAULT NULL::jsonb, IN pv_status character varying DEFAULT NULL::character varying, IN pv_previous_status character varying DEFAULT NULL::character varying, IN pv_imported_by character varying DEFAULT NULL::character varying, IN pv_imported_date timestamp without time zone DEFAULT NULL::timestamp without time zone, IN _v_username character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_username" character varying := COALESCE(NULLIF(trim("_v_username"), ''), 'system');
BEGIN
    IF "pv_mod_id" IS NULL OR trim("pv_mod_id") = '' THEN
        RAISE EXCEPTION 'mod_id is required';
    END IF;

    UPDATE "core"."def_mod"
    SET
        "mod_name" = COALESCE("pv_mod_name", "mod_name"),
        "config" = CASE WHEN "pv_config" IS NULL OR "pv_config" = '{}'::jsonb THEN "config" ELSE "pv_config" END,
        "config_ui" = CASE WHEN "pv_config_ui" IS NULL OR "pv_config_ui" = '{}'::jsonb THEN "config_ui" ELSE "pv_config_ui" END,
        "language" = CASE WHEN "pv_language" IS NULL OR "pv_language" = '{}'::jsonb THEN "language" ELSE "pv_language" END,
        "metadata" = CASE WHEN "pv_metadata" IS NULL OR "pv_metadata" = '{}'::jsonb THEN "metadata" ELSE "pv_metadata" END,
        "status" = COALESCE(NULLIF(trim("pv_status"), ''), "status"),
        "previous_status" = COALESCE(NULLIF(trim("pv_previous_status"), ''), "previous_status"),
        "imported_by" = COALESCE(NULLIF(trim("pv_imported_by"), ''), "imported_by"),
        "imported_date" = COALESCE("pv_imported_date", "imported_date"),
        "modified_by" = "v_username",
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "mod_id" = "pv_mod_id";

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Module % not found', "pv_mod_id";
    END IF;
END;
$$;


