CREATE PROCEDURE core.l057_app_menu_ins(IN pv_component_code character varying, IN pv_menu_key character varying, IN pv_parent_menu_id bigint DEFAULT NULL::bigint, IN pv_node_type character varying DEFAULT 'item'::character varying, IN pv_text character varying DEFAULT NULL::character varying, IN pv_text_i18n jsonb DEFAULT NULL::jsonb, IN pv_href character varying DEFAULT NULL::character varying, IN pv_target character varying DEFAULT '_self'::character varying, IN pv_icon character varying DEFAULT NULL::character varying, IN pv_icon_color character varying DEFAULT NULL::character varying, IN pv_badge character varying DEFAULT NULL::character varying, IN pv_badge_color character varying DEFAULT NULL::character varying, IN pv_position integer DEFAULT 0, IN pv_is_enabled boolean DEFAULT true)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NULLIF(BTRIM(pv_component_code), '') IS NULL OR NULLIF(BTRIM(pv_menu_key), '') IS NULL THEN
        RAISE EXCEPTION 'component_code and menu_key are required';
    END IF;
    INSERT INTO core.app_menu (component_code, menu_key, parent_menu_id, node_type, text, text_i18n, href, target, icon, icon_color, badge, badge_color, position, is_enabled)
    VALUES (BTRIM(pv_component_code), BTRIM(pv_menu_key), pv_parent_menu_id,
            COALESCE(NULLIF(BTRIM(pv_node_type), ''), 'item'), pv_text, pv_text_i18n, pv_href,
            COALESCE(NULLIF(BTRIM(pv_target), ''), '_self'), pv_icon, pv_icon_color, pv_badge,
            pv_badge_color, COALESCE(pv_position, 0), COALESCE(pv_is_enabled, TRUE));
EXCEPTION
    WHEN unique_violation THEN RAISE EXCEPTION 'Menu component="%" key="%" already exists', pv_component_code, pv_menu_key;
    WHEN foreign_key_violation THEN RAISE EXCEPTION 'Parent menu % does not exist', pv_parent_menu_id;
