-- TOC entry 392 (class 1255 OID 20315)
-- Name: l061_deflang_upd(character varying, character varying, text, character varying, character varying); Type: PROCEDURE; Schema: core; Owner: app_user
--

CREATE PROCEDURE core.l061_deflang_upd(IN pv_langid character varying, IN pv_langname character varying, IN pv_langvalue text, IN pv_status character varying DEFAULT NULL::character varying, IN "SESSIONINFO_USERNAME" character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE v_row_count integer;
BEGIN
    IF NULLIF(BTRIM(pv_langvalue), '') IS NULL THEN RAISE EXCEPTION 'LANGVALUE is required'; END IF;
    UPDATE core.deflang
       SET langvalue = pv_langvalue
     WHERE langid = BTRIM(pv_langid) AND langname = BTRIM(pv_langname);
    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    IF v_row_count = 0 THEN RAISE EXCEPTION 'Language % / % was not found', pv_langid, pv_langname; END IF;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'Failed to update language: %', SQLERRM;
END;
$$;


