--
-- TOC entry 444 (class 1255 OID 20316)
-- Name: l065_sys_var_del(character varying, character varying, character varying); Type: PROCEDURE; Schema: core; Owner: app_user
--

CREATE PROCEDURE core.l065_sys_var_del(IN pv_group_name character varying, IN pv_var_name character varying, IN "SESSIONINFO_USERNAME" character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE v_row_count integer;
BEGIN
    DELETE FROM core.sys_var WHERE group_name=BTRIM(pv_group_name) AND var_name=BTRIM(pv_var_name);
    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    IF v_row_count = 0 THEN RAISE EXCEPTION 'System variable % / % was not found', pv_group_name, pv_var_name; END IF;
EXCEPTION
    WHEN foreign_key_violation THEN RAISE EXCEPTION 'System variable % / % is referenced by another record', pv_group_name, pv_var_name;
    WHEN OTHERS THEN RAISE EXCEPTION 'Failed to delete system variable: %', SQLERRM;
END;
$$;


ALTER PROCEDURE core.l065_sys_var_del(IN pv_group_name character varying, IN pv_var_name character varying, IN "SESSIONINFO_USERNAME" character varying) OWNER TO app_user;

--
-- TOC entry 385 (class 1255 OID 20317)
-- Name: l065_sys_var_ins(character varying, character varying, text, text, character varying, character varying, character varying); Type: PROCEDURE; Schema: core; Owner: app_user
--

CREATE PROCEDURE core.l065_sys_var_ins(IN pv_group_name character varying, IN pv_var_name character varying, IN pv_var_value text DEFAULT NULL::text, IN pv_var_desc text DEFAULT NULL::text, IN pv_data_type character varying DEFAULT NULL::character varying, IN pv_fix character varying DEFAULT NULL::character varying, IN "SESSIONINFO_USERNAME" character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NULLIF(BTRIM(pv_group_name), '') IS NULL THEN RAISE EXCEPTION 'GROUP_NAME is required'; END IF;
    IF NULLIF(BTRIM(pv_var_name), '') IS NULL THEN RAISE EXCEPTION 'VAR_NAME is required'; END IF;
    INSERT INTO core.sys_var (group_name,var_name,var_value,var_desc,data_type,fix)
    VALUES (BTRIM(pv_group_name),BTRIM(pv_var_name),pv_var_value,pv_var_desc,pv_data_type,NULLIF(BTRIM(pv_fix), '')::BOOLEAN);
EXCEPTION
    WHEN unique_violation THEN RAISE EXCEPTION 'System variable % / % already exists', pv_group_name, pv_var_name;
    WHEN OTHERS THEN RAISE EXCEPTION 'Failed to create system variable: %', SQLERRM;
END;
$$;


