--
-- TOC entry 369 (class 1255 OID 20319)
-- Name: s003_jsonb_object_from_text(text, jsonb); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s003_jsonb_object_from_text(p_value text, p_default jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_result" jsonb;
BEGIN
    IF "p_value" IS NULL OR btrim("p_value") = '' THEN
        RETURN "p_default";
    END IF;

    BEGIN
        "v_result" := "p_value"::jsonb;
    EXCEPTION
        WHEN others THEN
            RAISE EXCEPTION 'Invalid JSON object'
                USING ERRCODE = '22023';
    END;

    IF jsonb_typeof("v_result") <> 'object' THEN
        RAISE EXCEPTION 'JSON value must be an object'
            USING ERRCODE = '22023';
    END IF;

    RETURN "v_result";
END;
$$;


ALTER FUNCTION core.s003_jsonb_object_from_text(p_value text, p_default jsonb) OWNER TO app_user;

--
-- TOC entry 425 (class 1255 OID 20320)
-- Name: s003_module_add(text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s003_module_add(p_mod_id text DEFAULT NULL::text, p_mod_name text DEFAULT NULL::text, p_config text DEFAULT NULL::text, p_config_ui text DEFAULT NULL::text, p_language text DEFAULT NULL::text, p_metadata text DEFAULT NULL::text, p_status text DEFAULT 'active'::text, p_previous_status text DEFAULT NULL::text, p_imported_by text DEFAULT NULL::text, p_imported_date text DEFAULT NULL::text, "_v_UserName" text DEFAULT NULL::text, "_v_Email" text DEFAULT NULL::text, "_v_IsPrivilegedAccount" text DEFAULT 'false'::text, "_v_DataScope" text DEFAULT NULL::text, "_v_ModuleDataScope" text DEFAULT NULL::text, "_v_DefaultDataScope" text DEFAULT NULL::text) RETURNS TABLE(mod_id character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_mod_id" varchar := "core"."s003_normalize_mod_id"("p_mod_id");
    "v_mod_name" varchar := btrim(coalesce("p_mod_name", ''));
    "v_status" varchar := "core"."s003_normalize_status"("p_status", 'active');
    "v_user" varchar := coalesce(nullif(btrim("_v_Email"), ''), nullif(btrim("_v_UserName"), ''), 'system');
BEGIN
    IF "v_mod_name" = '' THEN
        RAISE EXCEPTION 'Module name is required'
            USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM "core"."def_mod" AS "m"
        WHERE "m"."mod_id" = "v_mod_id"
    ) THEN
        RAISE EXCEPTION 'Module already exists: %', "v_mod_id"
            USING ERRCODE = '23505';
    END IF;

    INSERT INTO "core"."def_mod"(
        "mod_id",
        "mod_name",
        "config",
        "config_ui",
        "language",
        "metadata",
        "status",
        "previous_status",
        "imported_by",
        "imported_date",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date"
    )
    VALUES (
        "v_mod_id",
        "v_mod_name",
        coalesce("core"."s003_jsonb_object_from_text"("p_config", '{}'::jsonb), '{}'::jsonb),
        coalesce("core"."s003_jsonb_object_from_text"("p_config_ui", '{}'::jsonb), '{}'::jsonb),
        coalesce("core"."s003_jsonb_object_from_text"("p_language", '{}'::jsonb), '{}'::jsonb),
        coalesce("core"."s003_jsonb_object_from_text"("p_metadata", '{}'::jsonb), '{}'::jsonb),
        "v_status",
        NULL,
        nullif(btrim(coalesce("p_imported_by", '')), ''),
        "core"."s003_timestamp_from_text"("p_imported_date"),
        "v_user",
        CURRENT_TIMESTAMP,
        "v_user",
        CURRENT_TIMESTAMP
    );

    RETURN QUERY SELECT "v_mod_id";
END;
$$;


ALTER FUNCTION core.s003_module_add(p_mod_id text, p_mod_name text, p_config text, p_config_ui text, p_language text, p_metadata text, p_status text, p_previous_status text, p_imported_by text, p_imported_date text, "_v_UserName" text, "_v_Email" text, "_v_IsPrivilegedAccount" text, "_v_DataScope" text, "_v_ModuleDataScope" text, "_v_DefaultDataScope" text) OWNER TO app_user;

--
-- TOC entry 326 (class 1255 OID 20321)
-- Name: s003_module_detail(integer, integer, integer, integer, text, text, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s003_module_detail(p_page integer DEFAULT 1, p_page_size integer DEFAULT 25, p_skip integer DEFAULT 0, p_take integer DEFAULT 1, p_sort text DEFAULT NULL::text, p_filter text DEFAULT NULL::text, p_filters text DEFAULT NULL::text, p_group text DEFAULT NULL::text, p_search_expr text DEFAULT NULL::text, p_search_operation text DEFAULT NULL::text, p_search_value text DEFAULT NULL::text, p_mod_id text DEFAULT NULL::text, "_v_UserName" text DEFAULT NULL::text, "_v_Email" text DEFAULT NULL::text, "_v_IsPrivilegedAccount" text DEFAULT 'false'::text, "_v_DataScope" text DEFAULT NULL::text, "_v_ModuleDataScope" text DEFAULT NULL::text, "_v_DefaultDataScope" text DEFAULT NULL::text) RETURNS TABLE(mod_id character varying, mod_name character varying, config jsonb, config_ui jsonb, language jsonb, metadata jsonb, status character varying, previous_status character varying, imported_by character varying, imported_date timestamp without time zone, created_by character varying, created_date timestamp without time zone, modified_by character varying, modified_date timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_mod_id" varchar := "core"."s003_normalize_mod_id"("p_mod_id");
BEGIN
    RETURN QUERY
    SELECT
        "m"."mod_id",
        "m"."mod_name",
        "m"."config",
        "m"."config_ui",
        "m"."language",
        "m"."metadata",
        "m"."status",
        "m"."previous_status",
        "m"."imported_by",
        "m"."imported_date",
        "m"."created_by",
        "m"."created_date",
        "m"."modified_by",
        "m"."modified_date"
    FROM "core"."def_mod" AS "m"
    WHERE "m"."mod_id" = "v_mod_id";

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Module % not found', "v_mod_id"
            USING ERRCODE = '02000';
    END IF;
END;
$$;


ALTER FUNCTION core.s003_module_detail(p_page integer, p_page_size integer, p_skip integer, p_take integer, p_sort text, p_filter text, p_filters text, p_group text, p_search_expr text, p_search_operation text, p_search_value text, p_mod_id text, "_v_UserName" text, "_v_Email" text, "_v_IsPrivilegedAccount" text, "_v_DataScope" text, "_v_ModuleDataScope" text, "_v_DefaultDataScope" text) OWNER TO app_user;

--
-- TOC entry 372 (class 1255 OID 20322)
-- Name: s003_module_edit(text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s003_module_edit(p_mod_id text DEFAULT NULL::text, p_mod_name text DEFAULT NULL::text, p_config text DEFAULT NULL::text, p_config_ui text DEFAULT NULL::text, p_language text DEFAULT NULL::text, p_metadata text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_previous_status text DEFAULT NULL::text, p_imported_by text DEFAULT NULL::text, p_imported_date text DEFAULT NULL::text, "_v_UserName" text DEFAULT NULL::text, "_v_Email" text DEFAULT NULL::text, "_v_IsPrivilegedAccount" text DEFAULT 'false'::text, "_v_DataScope" text DEFAULT NULL::text, "_v_ModuleDataScope" text DEFAULT NULL::text, "_v_DefaultDataScope" text DEFAULT NULL::text) RETURNS TABLE(mod_id character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_mod_id" varchar := "core"."s003_normalize_mod_id"("p_mod_id");
    "v_config" jsonb := "core"."s003_jsonb_object_from_text"("p_config");
    "v_config_ui" jsonb := "core"."s003_jsonb_object_from_text"("p_config_ui");
    "v_language" jsonb := "core"."s003_jsonb_object_from_text"("p_language");
    "v_metadata" jsonb := "core"."s003_jsonb_object_from_text"("p_metadata");
    "v_user" varchar := coalesce(nullif(btrim("_v_Email"), ''), nullif(btrim("_v_UserName"), ''), 'system');
    "v_current_status" varchar;
    "v_status" varchar;
BEGIN
    SELECT "m"."status"
    INTO "v_current_status"
    FROM "core"."def_mod" AS "m"
    WHERE "m"."mod_id" = "v_mod_id"
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Module % not found', "v_mod_id"
            USING ERRCODE = '02000';
    END IF;

    "v_status" := "core"."s003_normalize_status"("p_status", "v_current_status");

    UPDATE "core"."def_mod" AS "m"
    SET
        "mod_name" = coalesce(nullif(btrim(coalesce("p_mod_name", '')), ''), "m"."mod_name"),
        "config" = CASE WHEN "v_config" IS NULL OR "v_config" = '{}'::jsonb THEN "m"."config" ELSE "v_config" END,
        "config_ui" = CASE WHEN "v_config_ui" IS NULL OR "v_config_ui" = '{}'::jsonb THEN "m"."config_ui" ELSE "v_config_ui" END,
        "language" = CASE WHEN "v_language" IS NULL OR "v_language" = '{}'::jsonb THEN "m"."language" ELSE "v_language" END,
        "metadata" = CASE WHEN "v_metadata" IS NULL OR "v_metadata" = '{}'::jsonb THEN "m"."metadata" ELSE "v_metadata" END,
        "status" = "v_status",
        "previous_status" = CASE
            WHEN "v_status" IS DISTINCT FROM "v_current_status" THEN "v_current_status"
            ELSE "m"."previous_status"
        END,
        "imported_by" = coalesce(nullif(btrim(coalesce("p_imported_by", '')), ''), "m"."imported_by"),
        "imported_date" = "core"."s003_timestamp_from_text"("p_imported_date", "m"."imported_date"),
        "modified_by" = "v_user",
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "m"."mod_id" = "v_mod_id";

    RETURN QUERY SELECT "v_mod_id";
END;
$$;


ALTER FUNCTION core.s003_module_edit(p_mod_id text, p_mod_name text, p_config text, p_config_ui text, p_language text, p_metadata text, p_status text, p_previous_status text, p_imported_by text, p_imported_date text, "_v_UserName" text, "_v_Email" text, "_v_IsPrivilegedAccount" text, "_v_DataScope" text, "_v_ModuleDataScope" text, "_v_DefaultDataScope" text) OWNER TO app_user;

--
-- TOC entry 344 (class 1255 OID 20323)
-- Name: s003_normalize_mod_id(text); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s003_normalize_mod_id(p_mod_id text) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
DECLARE
    "v_mod_id" varchar := upper(btrim(coalesce("p_mod_id", '')));
BEGIN
    IF "v_mod_id" !~ '^[A-Z][A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Module code must contain exactly four uppercase letters or digits and start with a letter'
            USING ERRCODE = '22023';
    END IF;

    RETURN "v_mod_id";
END;
$_$;


ALTER FUNCTION core.s003_normalize_mod_id(p_mod_id text) OWNER TO app_user;

--
-- TOC entry 347 (class 1255 OID 20324)
-- Name: s003_normalize_status(text, text); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s003_normalize_status(p_status text, p_default text DEFAULT 'active'::text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_status" varchar := lower(btrim(coalesce(nullif("p_status", ''), "p_default")));
BEGIN
    IF "v_status" NOT IN ('draft', 'registered', 'active', 'disabled', 'retired', 'inactive', 'deleted') THEN
        RAISE EXCEPTION 'Unsupported module status: %', "v_status"
            USING ERRCODE = '22023';
    END IF;

    RETURN "v_status";
END;
$$;


ALTER FUNCTION core.s003_normalize_status(p_status text, p_default text) OWNER TO app_user;

--
-- TOC entry 315 (class 1255 OID 20325)
-- Name: s003_timestamp_from_text(text, timestamp without time zone); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s003_timestamp_from_text(p_value text, p_default timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF "p_value" IS NULL OR btrim("p_value") = '' THEN
        RETURN "p_default";
    END IF;

    BEGIN
        RETURN "p_value"::timestamp without time zone;
    EXCEPTION
        WHEN others THEN
            RAISE EXCEPTION 'Invalid timestamp: %', "p_value"
                USING ERRCODE = '22023';
    END;
END;
$$;


ALTER FUNCTION core.s003_timestamp_from_text(p_value text, p_default timestamp without time zone) OWNER TO app_user;

--
-- TOC entry 428 (class 1255 OID 20326)
-- Name: s011_dashboard_add(character varying, character varying, character varying, text, character varying, text, text, text, text, text, text, text, boolean, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s011_dashboard_add(p_mod_id character varying DEFAULT NULL::character varying, p_mod_name_en character varying DEFAULT NULL::character varying, p_mod_name_vi character varying DEFAULT NULL::character varying, p_data_sources text DEFAULT NULL::text, p_height character varying DEFAULT '100%'::character varying, p_description_en text DEFAULT NULL::text, p_description_vi text DEFAULT NULL::text, p_tags text DEFAULT '[]'::text, p_help_markdown_en text DEFAULT NULL::text, p_help_markdown_vi text DEFAULT NULL::text, p_ai_screen_purpose_en text DEFAULT NULL::text, p_ai_screen_purpose_vi text DEFAULT NULL::text, p_publish_menu boolean DEFAULT false, p_menu_component character varying DEFAULT NULL::character varying, p_menu_id character varying DEFAULT NULL::character varying, p_owner_menu_id character varying DEFAULT NULL::character varying, p_menu_icon character varying DEFAULT 'chart'::character varying, p_menu_position numeric DEFAULT 0, p_menu_name_en character varying DEFAULT NULL::character varying, p_menu_name_vi character varying DEFAULT NULL::character varying, "_v_UserName" character varying DEFAULT NULL::character varying, "_v_Email" character varying DEFAULT NULL::character varying, "_v_IsPrivilegedAccount" character varying DEFAULT 'false'::character varying, "_v_DataScope" character varying DEFAULT NULL::character varying, "_v_ModuleDataScope" character varying DEFAULT NULL::character varying, "_v_DefaultDataScope" character varying DEFAULT NULL::character varying) RETURNS TABLE(mod_id character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    "v_mod_id" varchar := upper(btrim(coalesce("p_mod_id", '')));
    "v_mod_name_en" varchar;
    "v_mod_name_vi" varchar;
    "v_user" varchar := coalesce(nullif(btrim("_v_Email"), ''), nullif(btrim("_v_UserName"), ''), 'system');
    "v_data_sources" jsonb := "core"."s011_jsonb_array_from_text"("p_data_sources", '[]'::jsonb);
    "v_tags" jsonb := "core"."s011_jsonb_array_from_text"("p_tags", '[]'::jsonb);
    "v_missing_sources" text;
    "v_layout_xml" text;
    "v_config" jsonb;
    "v_config_ui" jsonb;
    "v_language" jsonb;
    "v_metadata" jsonb;
    "v_existing_menu_module" varchar;
BEGIN
    IF "v_mod_id" !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid dashboard module id: %', "p_mod_id"
            USING ERRCODE = '22023';
    END IF;

    "v_mod_name_en" := coalesce(nullif(btrim(coalesce("p_mod_name_en", '')), ''), "v_mod_id");
    "v_mod_name_vi" := coalesce(nullif(btrim(coalesce("p_mod_name_vi", '')), ''), "v_mod_id");

    IF EXISTS (SELECT 1 FROM "core"."def_mod" AS "m" WHERE "m"."mod_id" = "v_mod_id") THEN
        RAISE EXCEPTION 'Dashboard module % already exists', "v_mod_id"
            USING ERRCODE = '23505';
    END IF;

    IF jsonb_array_length("v_data_sources") = 0 THEN
        RAISE EXCEPTION 'At least one dashboard data source is required'
            USING ERRCODE = '22023';
    END IF;

    SELECT string_agg("src"."value", ', ')
    INTO "v_missing_sources"
    FROM jsonb_array_elements_text("v_data_sources") AS "src"("value")
    WHERE NOT EXISTS (
        SELECT 1
        FROM "core"."def_source" AS "ds"
        WHERE "ds"."source_name" = "src"."value"
    );

    IF "v_missing_sources" IS NOT NULL THEN
        RAISE EXCEPTION 'Unknown dashboard data source(s): %', "v_missing_sources"
            USING ERRCODE = '22023';
    END IF;

    IF "p_publish_menu" THEN
        IF nullif(btrim(coalesce("p_menu_component", '')), '') IS NULL
           OR nullif(btrim(coalesce("p_menu_id", '')), '') IS NULL THEN
            RAISE EXCEPTION 'Menu component and menu id are required when publish menu is enabled'
                USING ERRCODE = '22023';
        END IF;

        SELECT "dm"."module_id"
        INTO "v_existing_menu_module"
        FROM "core"."def_menu" AS "dm"
        WHERE "dm"."component" = "p_menu_component"
          AND "dm"."menu_id" = "p_menu_id";

        IF "v_existing_menu_module" IS NOT NULL AND "v_existing_menu_module" <> "v_mod_id" THEN
            RAISE EXCEPTION 'Menu %.% already belongs to module %',
                "p_menu_component", "p_menu_id", "v_existing_menu_module"
                USING ERRCODE = '23505';
        END IF;
    END IF;

    "v_layout_xml" := format($xml$<?xml version="1.0" encoding="utf-8"?>
<Dashboard RequestParameters="false">
  <Title Text="%s" />
</Dashboard>
$xml$, "v_mod_id");

    "v_config" := jsonb_build_object(
        'schemaVersion', 1,
        'engine', 'devexpress-dashboard',
        'dataSources', "v_data_sources",
        'features', jsonb_build_object(
            'allowCustomSql', false,
            'allowCreateNewJsonConnection', false
        )
    );

    "v_config_ui" := jsonb_build_object(
        'schemaVersion', 1,
        'height', coalesce(nullif(btrim("p_height"), ''), '100%'),
        'layoutXml', "v_layout_xml"
    );

    "v_language" := jsonb_build_object(
        'en', jsonb_build_object('Module$Name', "v_mod_name_en", 'Page$Title', "v_mod_name_en"),
        'vi', jsonb_build_object('Module$Name', "v_mod_name_vi", 'Page$Title', "v_mod_name_vi")
    );

    "v_metadata" := jsonb_build_object(
        'schemaVersion', 1,
        'description', jsonb_build_object('en', coalesce("p_description_en", ''), 'vi', coalesce("p_description_vi", '')),
        'tags', "v_tags",
        'help', jsonb_build_object(
            'en', jsonb_build_object('format', 'markdown', 'markdown', coalesce("p_help_markdown_en", ''), 'text', coalesce("p_help_markdown_en", '')),
            'vi', jsonb_build_object('format', 'markdown', 'markdown', coalesce("p_help_markdown_vi", ''), 'text', coalesce("p_help_markdown_vi", ''))
        ),
        'ai', jsonb_build_object(
            'screenPurpose', jsonb_build_object('en', coalesce("p_ai_screen_purpose_en", ''), 'vi', coalesce("p_ai_screen_purpose_vi", ''))
        )
    );

    INSERT INTO "core"."def_mod"
    (
        "mod_id",
        "mod_name",
        "config",
        "config_ui",
        "language",
        "metadata",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date"
    )
    VALUES
    (
        "v_mod_id",
        "v_mod_name_en",
        "v_config",
        "v_config_ui",
        "v_language",
        "v_metadata",
        "v_user",
        CURRENT_TIMESTAMP,
        "v_user",
        CURRENT_TIMESTAMP
    );

    IF "p_publish_menu" THEN
        INSERT INTO "core"."def_menu"
        (
            "component",
            "menu_id",
            "owner_menu_id",
            "icon",
            "module_id",
            "position",
            "param",
            "language"
        )
        VALUES
        (
            "p_menu_component",
            "p_menu_id",
            nullif(btrim(coalesce("p_owner_menu_id", '')), ''),
            coalesce(nullif(btrim("p_menu_icon"), ''), 'chart'),
            "v_mod_id",
            coalesce("p_menu_position", 0),
            NULL,
            jsonb_build_object(
                'en', jsonb_build_object('Name', coalesce(nullif(btrim("p_menu_name_en"), ''), "v_mod_name_en")),
                'vi', jsonb_build_object('Name', coalesce(nullif(btrim("p_menu_name_vi"), ''), "v_mod_name_vi"))
            )
        )
        ON CONFLICT ("component", "menu_id") DO UPDATE
        SET
            "owner_menu_id" = EXCLUDED."owner_menu_id",
            "icon" = EXCLUDED."icon",
            "module_id" = EXCLUDED."module_id",
            "position" = EXCLUDED."position",
            "param" = EXCLUDED."param",
            "language" = EXCLUDED."language";
    END IF;

    RETURN QUERY SELECT "v_mod_id";
END;
$_$;


ALTER FUNCTION core.s011_dashboard_add(p_mod_id character varying, p_mod_name_en character varying, p_mod_name_vi character varying, p_data_sources text, p_height character varying, p_description_en text, p_description_vi text, p_tags text, p_help_markdown_en text, p_help_markdown_vi text, p_ai_screen_purpose_en text, p_ai_screen_purpose_vi text, p_publish_menu boolean, p_menu_component character varying, p_menu_id character varying, p_owner_menu_id character varying, p_menu_icon character varying, p_menu_position numeric, p_menu_name_en character varying, p_menu_name_vi character varying, "_v_UserName" character varying, "_v_Email" character varying, "_v_IsPrivilegedAccount" character varying, "_v_DataScope" character varying, "_v_ModuleDataScope" character varying, "_v_DefaultDataScope" character varying) OWNER TO app_user;

--
-- TOC entry 422 (class 1255 OID 20328)
-- Name: s011_dashboard_detail(integer, integer, integer, integer, text, text, text, text, text, text, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s011_dashboard_detail(p_page integer DEFAULT 1, p_page_size integer DEFAULT 25, p_skip integer DEFAULT 0, p_take integer DEFAULT 1, p_sort text DEFAULT NULL::text, p_filter text DEFAULT NULL::text, p_filters text DEFAULT NULL::text, p_group text DEFAULT NULL::text, p_search_expr text DEFAULT NULL::text, p_search_operation text DEFAULT NULL::text, p_search_value text DEFAULT NULL::text, p_mod_id character varying DEFAULT NULL::character varying, "_v_UserName" character varying DEFAULT NULL::character varying, "_v_Email" character varying DEFAULT NULL::character varying, "_v_IsPrivilegedAccount" character varying DEFAULT 'false'::character varying, "_v_DataScope" character varying DEFAULT NULL::character varying, "_v_ModuleDataScope" character varying DEFAULT NULL::character varying, "_v_DefaultDataScope" character varying DEFAULT NULL::character varying) RETURNS TABLE(mod_id character varying, mod_name character varying, config jsonb, config_ui jsonb, language jsonb, metadata jsonb, menu_component character varying, menu_id character varying, owner_menu_id character varying, menu_icon character varying, menu_position numeric, menu_name_en text, menu_name_vi text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    "v_mod_id" varchar := upper(btrim(coalesce("p_mod_id", '')));
BEGIN
    IF "v_mod_id" !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid dashboard module id: %', "p_mod_id"
            USING ERRCODE = '22023';
    END IF;

    RETURN QUERY
    SELECT
        "m"."mod_id",
        "m"."mod_name",
        "m"."config",
        "m"."config_ui",
        "m"."language",
        "m"."metadata",
        "mn"."component",
        "mn"."menu_id",
        "mn"."owner_menu_id",
        "mn"."icon",
        "mn"."position",
        "mn"."language"->'en'->>'Name',
        "mn"."language"->'vi'->>'Name'
    FROM "core"."def_mod" AS "m"
    LEFT JOIN LATERAL (
        SELECT
            "dm"."component",
            "dm"."menu_id",
            "dm"."owner_menu_id",
            "dm"."icon",
            "dm"."position",
            "dm"."language"
        FROM "core"."def_menu" AS "dm"
        WHERE "dm"."module_id" = "m"."mod_id"
        ORDER BY "dm"."component", "dm"."menu_id"
        LIMIT 1
    ) AS "mn" ON true
    WHERE "m"."mod_id" = "v_mod_id"
      AND "m"."mod_id" LIKE 'D%';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Dashboard module % not found', "v_mod_id"
            USING ERRCODE = '02000';
    END IF;
END;
$_$;


ALTER FUNCTION core.s011_dashboard_detail(p_page integer, p_page_size integer, p_skip integer, p_take integer, p_sort text, p_filter text, p_filters text, p_group text, p_search_expr text, p_search_operation text, p_search_value text, p_mod_id character varying, "_v_UserName" character varying, "_v_Email" character varying, "_v_IsPrivilegedAccount" character varying, "_v_DataScope" character varying, "_v_ModuleDataScope" character varying, "_v_DefaultDataScope" character varying) OWNER TO app_user;

--
-- TOC entry 354 (class 1255 OID 20329)
-- Name: s011_dashboard_duplicate(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s011_dashboard_duplicate(p_source_mod_id character varying DEFAULT NULL::character varying, p_new_mod_id character varying DEFAULT NULL::character varying, "_v_UserName" character varying DEFAULT NULL::character varying, "_v_Email" character varying DEFAULT NULL::character varying, "_v_IsPrivilegedAccount" character varying DEFAULT 'false'::character varying, "_v_DataScope" character varying DEFAULT NULL::character varying, "_v_ModuleDataScope" character varying DEFAULT NULL::character varying, "_v_DefaultDataScope" character varying DEFAULT NULL::character varying) RETURNS TABLE(mod_id character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    "v_source_mod_id" varchar := upper(btrim(coalesce("p_source_mod_id", '')));
    "v_new_mod_id" varchar := upper(btrim(coalesce("p_new_mod_id", '')));
    "v_user" varchar := coalesce(nullif(btrim("_v_Email"), ''), nullif(btrim("_v_UserName"), ''), 'system');
    "v_source" record;
BEGIN
    IF "v_source_mod_id" !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid source dashboard module id: %', "p_source_mod_id"
            USING ERRCODE = '22023';
    END IF;

    IF "v_new_mod_id" !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid new dashboard module id: %', "p_new_mod_id"
            USING ERRCODE = '22023';
    END IF;

    SELECT *
    INTO "v_source"
    FROM "core"."def_mod" AS "m"
    WHERE "m"."mod_id" = "v_source_mod_id";

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Source dashboard module % not found', "v_source_mod_id"
            USING ERRCODE = '02000';
    END IF;

    IF EXISTS (SELECT 1 FROM "core"."def_mod" AS "m" WHERE "m"."mod_id" = "v_new_mod_id") THEN
        RAISE EXCEPTION 'Dashboard module % already exists', "v_new_mod_id"
            USING ERRCODE = '23505';
    END IF;

    INSERT INTO "core"."def_mod"
    (
        "mod_id",
        "mod_name",
        "config",
        "config_ui",
        "language",
        "metadata",
        "created_by",
        "created_date",
        "modified_by",
        "modified_date"
    )
    VALUES
    (
        "v_new_mod_id",
        "v_source"."mod_name",
        "v_source"."config",
        "v_source"."config_ui",
        "v_source"."language",
        "v_source"."metadata",
        "v_user",
        CURRENT_TIMESTAMP,
        "v_user",
        CURRENT_TIMESTAMP
    );

    RETURN QUERY SELECT "v_new_mod_id";
END;
$_$;


ALTER FUNCTION core.s011_dashboard_duplicate(p_source_mod_id character varying, p_new_mod_id character varying, "_v_UserName" character varying, "_v_Email" character varying, "_v_IsPrivilegedAccount" character varying, "_v_DataScope" character varying, "_v_ModuleDataScope" character varying, "_v_DefaultDataScope" character varying) OWNER TO app_user;

--
-- TOC entry 313 (class 1255 OID 20330)
-- Name: s011_dashboard_edit(character varying, character varying, character varying, text, character varying, text, text, text, text, text, text, text, boolean, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s011_dashboard_edit(p_mod_id character varying DEFAULT NULL::character varying, p_mod_name_en character varying DEFAULT NULL::character varying, p_mod_name_vi character varying DEFAULT NULL::character varying, p_data_sources text DEFAULT NULL::text, p_height character varying DEFAULT '100%'::character varying, p_description_en text DEFAULT NULL::text, p_description_vi text DEFAULT NULL::text, p_tags text DEFAULT '[]'::text, p_help_markdown_en text DEFAULT NULL::text, p_help_markdown_vi text DEFAULT NULL::text, p_ai_screen_purpose_en text DEFAULT NULL::text, p_ai_screen_purpose_vi text DEFAULT NULL::text, p_publish_menu boolean DEFAULT false, p_menu_component character varying DEFAULT NULL::character varying, p_menu_id character varying DEFAULT NULL::character varying, p_owner_menu_id character varying DEFAULT NULL::character varying, p_menu_icon character varying DEFAULT 'chart'::character varying, p_menu_position numeric DEFAULT 0, p_menu_name_en character varying DEFAULT NULL::character varying, p_menu_name_vi character varying DEFAULT NULL::character varying, "_v_UserName" character varying DEFAULT NULL::character varying, "_v_Email" character varying DEFAULT NULL::character varying, "_v_IsPrivilegedAccount" character varying DEFAULT 'false'::character varying, "_v_DataScope" character varying DEFAULT NULL::character varying, "_v_ModuleDataScope" character varying DEFAULT NULL::character varying, "_v_DefaultDataScope" character varying DEFAULT NULL::character varying) RETURNS TABLE(mod_id character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    "v_mod_id" varchar := upper(btrim(coalesce("p_mod_id", '')));
    "v_mod_name_en" varchar;
    "v_mod_name_vi" varchar;
    "v_user" varchar := coalesce(nullif(btrim("_v_Email"), ''), nullif(btrim("_v_UserName"), ''), 'system');
    "v_data_sources" jsonb := "core"."s011_jsonb_array_from_text"("p_data_sources", '[]'::jsonb);
    "v_tags" jsonb := "core"."s011_jsonb_array_from_text"("p_tags", '[]'::jsonb);
    "v_missing_sources" text;
    "v_existing_layout_xml" text;
    "v_config" jsonb;
    "v_config_ui" jsonb;
    "v_language" jsonb;
    "v_metadata" jsonb;
    "v_existing_menu_module" varchar;
BEGIN
    IF "v_mod_id" !~ '^D[A-Z0-9]{3}$' THEN
        RAISE EXCEPTION 'Invalid dashboard module id: %', "p_mod_id"
            USING ERRCODE = '22023';
    END IF;

    "v_mod_name_en" := coalesce(nullif(btrim(coalesce("p_mod_name_en", '')), ''), "v_mod_id");
    "v_mod_name_vi" := coalesce(nullif(btrim(coalesce("p_mod_name_vi", '')), ''), "v_mod_id");

    SELECT "m"."config_ui"->>'layoutXml'
    INTO "v_existing_layout_xml"
    FROM "core"."def_mod" AS "m"
    WHERE "m"."mod_id" = "v_mod_id"
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Dashboard module % not found', "v_mod_id"
            USING ERRCODE = '02000';
    END IF;

    IF jsonb_array_length("v_data_sources") = 0 THEN
        RAISE EXCEPTION 'At least one dashboard data source is required'
            USING ERRCODE = '22023';
    END IF;

    SELECT string_agg("src"."value", ', ')
    INTO "v_missing_sources"
    FROM jsonb_array_elements_text("v_data_sources") AS "src"("value")
    WHERE NOT EXISTS (
        SELECT 1
        FROM "core"."def_source" AS "ds"
        WHERE "ds"."source_name" = "src"."value"
    );

    IF "v_missing_sources" IS NOT NULL THEN
        RAISE EXCEPTION 'Unknown dashboard data source(s): %', "v_missing_sources"
            USING ERRCODE = '22023';
    END IF;

    IF nullif("v_existing_layout_xml", '') IS NULL THEN
        "v_existing_layout_xml" := format($xml$<?xml version="1.0" encoding="utf-8"?>
<Dashboard RequestParameters="false">
  <Title Text="%s" />
</Dashboard>
$xml$, "v_mod_id");
    END IF;

    IF "p_publish_menu" THEN
        IF nullif(btrim(coalesce("p_menu_component", '')), '') IS NULL
           OR nullif(btrim(coalesce("p_menu_id", '')), '') IS NULL THEN
            RAISE EXCEPTION 'Menu component and menu id are required when publish menu is enabled'
                USING ERRCODE = '22023';
        END IF;

        SELECT "dm"."module_id"
        INTO "v_existing_menu_module"
        FROM "core"."def_menu" AS "dm"
        WHERE "dm"."component" = "p_menu_component"
          AND "dm"."menu_id" = "p_menu_id";

        IF "v_existing_menu_module" IS NOT NULL AND "v_existing_menu_module" <> "v_mod_id" THEN
            RAISE EXCEPTION 'Menu %.% already belongs to module %',
                "p_menu_component", "p_menu_id", "v_existing_menu_module"
                USING ERRCODE = '23505';
        END IF;
    END IF;

    "v_config" := jsonb_build_object(
        'schemaVersion', 1,
        'engine', 'devexpress-dashboard',
        'dataSources', "v_data_sources",
        'features', jsonb_build_object('allowCustomSql', false, 'allowCreateNewJsonConnection', false)
    );

    "v_config_ui" := jsonb_build_object(
        'schemaVersion', 1,
        'height', coalesce(nullif(btrim("p_height"), ''), '100%'),
        'layoutXml', "v_existing_layout_xml"
    );

    "v_language" := jsonb_build_object(
        'en', jsonb_build_object('Module$Name', "v_mod_name_en", 'Page$Title', "v_mod_name_en"),
        'vi', jsonb_build_object('Module$Name', "v_mod_name_vi", 'Page$Title', "v_mod_name_vi")
    );

    "v_metadata" := jsonb_build_object(
        'schemaVersion', 1,
        'description', jsonb_build_object('en', coalesce("p_description_en", ''), 'vi', coalesce("p_description_vi", '')),
        'tags', "v_tags",
        'help', jsonb_build_object(
            'en', jsonb_build_object('format', 'markdown', 'markdown', coalesce("p_help_markdown_en", ''), 'text', coalesce("p_help_markdown_en", '')),
            'vi', jsonb_build_object('format', 'markdown', 'markdown', coalesce("p_help_markdown_vi", ''), 'text', coalesce("p_help_markdown_vi", ''))
        ),
        'ai', jsonb_build_object('screenPurpose', jsonb_build_object('en', coalesce("p_ai_screen_purpose_en", ''), 'vi', coalesce("p_ai_screen_purpose_vi", '')))
    );

    UPDATE "core"."def_mod" AS "m"
    SET
        "mod_name" = "v_mod_name_en",
        "config" = "v_config",
        "config_ui" = "v_config_ui",
        "language" = "v_language",
        "metadata" = "v_metadata",
        "modified_by" = "v_user",
        "modified_date" = CURRENT_TIMESTAMP
    WHERE "m"."mod_id" = "v_mod_id";

    IF "p_publish_menu" THEN
        DELETE FROM "core"."def_menu" AS "dm"
        WHERE "dm"."module_id" = "v_mod_id"
          AND ("dm"."component" <> "p_menu_component" OR "dm"."menu_id" <> "p_menu_id");

        INSERT INTO "core"."def_menu"
        (
            "component",
            "menu_id",
            "owner_menu_id",
            "icon",
            "module_id",
            "position",
            "param",
            "language"
        )
        VALUES
        (
            "p_menu_component",
            "p_menu_id",
            nullif(btrim(coalesce("p_owner_menu_id", '')), ''),
            coalesce(nullif(btrim("p_menu_icon"), ''), 'chart'),
            "v_mod_id",
            coalesce("p_menu_position", 0),
            NULL,
            jsonb_build_object(
                'en', jsonb_build_object('Name', coalesce(nullif(btrim("p_menu_name_en"), ''), "v_mod_name_en")),
                'vi', jsonb_build_object('Name', coalesce(nullif(btrim("p_menu_name_vi"), ''), "v_mod_name_vi"))
            )
        )
        ON CONFLICT ("component", "menu_id") DO UPDATE
        SET
            "owner_menu_id" = EXCLUDED."owner_menu_id",
            "icon" = EXCLUDED."icon",
            "module_id" = EXCLUDED."module_id",
            "position" = EXCLUDED."position",
            "param" = EXCLUDED."param",
            "language" = EXCLUDED."language";
    ELSE
        DELETE FROM "core"."def_menu" AS "dm"
        WHERE "dm"."module_id" = "v_mod_id";
    END IF;

    RETURN QUERY SELECT "v_mod_id";
END;
$_$;


ALTER FUNCTION core.s011_dashboard_edit(p_mod_id character varying, p_mod_name_en character varying, p_mod_name_vi character varying, p_data_sources text, p_height character varying, p_description_en text, p_description_vi text, p_tags text, p_help_markdown_en text, p_help_markdown_vi text, p_ai_screen_purpose_en text, p_ai_screen_purpose_vi text, p_publish_menu boolean, p_menu_component character varying, p_menu_id character varying, p_owner_menu_id character varying, p_menu_icon character varying, p_menu_position numeric, p_menu_name_en character varying, p_menu_name_vi character varying, "_v_UserName" character varying, "_v_Email" character varying, "_v_IsPrivilegedAccount" character varying, "_v_DataScope" character varying, "_v_ModuleDataScope" character varying, "_v_DefaultDataScope" character varying) OWNER TO app_user;

--
-- TOC entry 365 (class 1255 OID 20332)
-- Name: s011_jsonb_array_from_text(text, jsonb); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s011_jsonb_array_from_text(p_value text, p_default jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_result" jsonb;
BEGIN
    IF "p_value" IS NULL OR btrim("p_value") = '' THEN
        RETURN "p_default";
    END IF;

    "v_result" := "p_value"::jsonb;

    IF jsonb_typeof("v_result") <> 'array' THEN
        RAISE EXCEPTION 'Value must be a JSON array'
            USING ERRCODE = '22023';
    END IF;

    RETURN "v_result";
END;
$$;


ALTER FUNCTION core.s011_jsonb_array_from_text(p_value text, p_default jsonb) OWNER TO app_user;

--
-- TOC entry 384 (class 1255 OID 20333)
-- Name: s011_lookup_components(character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: core; Owner: app_user
--

CREATE FUNCTION core.s011_lookup_components("_v_UserName" character varying DEFAULT NULL::character varying, "_v_Email" character varying DEFAULT NULL::character varying, "_v_IsPrivilegedAccount" character varying DEFAULT 'false'::character varying, "_v_DataScope" character varying DEFAULT NULL::character varying, "_v_ModuleDataScope" character varying DEFAULT NULL::character varying, "_v_DefaultDataScope" character varying DEFAULT NULL::character varying) RETURNS TABLE(value character varying, text character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        "c"."code"::varchar AS "value",
        "c"."code"::varchar AS "text"
    FROM "core"."def_component" AS "c"
    WHERE COALESCE("c"."is_deleted", false) = false
    ORDER BY "c"."code";
END;
$$;


