CREATE FUNCTION core.s011_lookup_data_sources("_v_UserName" character varying DEFAULT NULL::character varying, "_v_Email" character varying DEFAULT NULL::character varying, "_v_IsPrivilegedAccount" character varying DEFAULT 'false'::character varying, "_v_DataScope" character varying DEFAULT NULL::character varying, "_v_ModuleDataScope" character varying DEFAULT NULL::character varying, "_v_DefaultDataScope" character varying DEFAULT NULL::character varying) RETURNS TABLE(value character varying, type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        "ds"."source_name",
        COALESCE("ds"."config"->>'data_source_type', "ds"."type", '')::varchar
    FROM "core"."def_source" AS "ds"
    ORDER BY "ds"."source_name";
END;
$$;


