CREATE FUNCTION core.s011_lookup_menus_by_component(p_component character varying DEFAULT NULL::character varying, "_v_UserName" character varying DEFAULT NULL::character varying, "_v_Email" character varying DEFAULT NULL::character varying, "_v_IsPrivilegedAccount" character varying DEFAULT 'false'::character varying, "_v_DataScope" character varying DEFAULT NULL::character varying, "_v_ModuleDataScope" character varying DEFAULT NULL::character varying, "_v_DefaultDataScope" character varying DEFAULT NULL::character varying) RETURNS TABLE(value character varying, text character varying)
