--
-- TOC entry 360 (class 1255 OID 20338)
-- Name: upload_session_delete(character varying, character varying, character varying); Type: PROCEDURE; Schema: ops; Owner: app_user
--

CREATE PROCEDURE ops.upload_session_delete(IN pv_upload_id character varying, IN pv_result_message character varying DEFAULT NULL::character varying, IN "_v_UserName" character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_actor"   VARCHAR;
    "v_exists"  BOOLEAN;
BEGIN
    "v_actor" := COALESCE(NULLIF(TRIM(COALESCE("_v_UserName", '')), ''), 'system');

    SELECT TRUE INTO "v_exists"
    FROM "ops"."upload_session"
    WHERE "upload_id" = "pv_upload_id";

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Upload session "%" not found', "pv_upload_id";
    END IF;

    DELETE FROM "ops"."upload_session"
    WHERE "upload_id" = "pv_upload_id";

    "pv_result_message" := 'Deleted upload session ' || "pv_upload_id" || ' by ' || "v_actor";
END;
$$;


ALTER PROCEDURE ops.upload_session_delete(IN pv_upload_id character varying, IN pv_result_message character varying, IN "_v_UserName" character varying) OWNER TO app_user;

--
-- TOC entry 358 (class 1255 OID 20339)
-- Name: upload_session_invalidate(character varying, character varying, character varying); Type: PROCEDURE; Schema: ops; Owner: app_user
--

CREATE PROCEDURE ops.upload_session_invalidate(IN pv_upload_id character varying, IN pv_result_message character varying DEFAULT NULL::character varying, IN "_v_UserName" character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    "v_actor"   VARCHAR;
    "v_status"  VARCHAR;
BEGIN
    "v_actor" := COALESCE(NULLIF(TRIM(COALESCE("_v_UserName", '')), ''), 'system');

    SELECT "status" INTO "v_status"
    FROM "ops"."upload_session"
    WHERE "upload_id" = "pv_upload_id";

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Upload session "%" not found', "pv_upload_id";
    END IF;

    IF "v_status" <> 'active' THEN
        RAISE EXCEPTION 'Only active sessions can be invalidated (current: %)', "v_status";
    END IF;

    UPDATE "ops"."upload_session"
    SET "status" = 'aborted'
    WHERE "upload_id" = "pv_upload_id" AND "status" = 'active';

    "pv_result_message" := 'Invalidated upload session ' || "pv_upload_id" || ' by ' || "v_actor";
END;
$$;


ALTER PROCEDURE ops.upload_session_invalidate(IN pv_upload_id character varying, IN pv_result_message character varying, IN "_v_UserName" character varying) OWNER TO app_user;

